{
  "name": "DigiSHE",
  "description": "A simple digital record-keeping MVP for women-led MSMEs to track sales, expenses, and view weekly business performance with ease.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type BusinessType = 'Food' | 'Fashion' | 'Trading' | 'Production' | 'Services';

export interface User {
  phoneNumber: string;
  name: string;
  hasCompletedOnboarding: boolean;
}

export interface Business {
  name: string;
  type: BusinessType;
  location?: string;
  startDate: string;
}

export interface Transaction {
  id: string;
  userId: string;
  type: 'sale' | 'expense';
  amount: number;
  date: string;
  note?: string;
}

export interface AppState {
  user: User | null;
  business: Business | null;
  transactions: Transaction[];
}

import { GoogleGenAI } from "@google/genai";
import { Transaction, Business } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getBusinessInsight(business: Business, transactions: Transaction[]): Promise<string> {
  const recentTransactions = transactions.slice(-10);
  const sales = recentTransactions.filter(t => t.type === 'sale').reduce((acc, curr) => acc + curr.amount, 0);
  const expenses = recentTransactions.filter(t => t.type === 'expense').reduce((acc, curr) => acc + curr.amount, 0);

  const prompt = `
    Business: ${business.name} (${business.type})
    Recent Stats: Total Sales $${sales}, Total Expenses $${expenses}
    Task: Give a very short, encouraging, and simple business tip (one sentence) for a woman business owner. 
    Focus on growth and financial health. Keep the language simple and friendly.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });
    return response.text || "Keep up the great work! Your records are looking good.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Every entry brings you closer to your business goals. Keep going!";
  }
}

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'sale' | 'expense' | 'outline';
  size?: 'sm' | 'md' | 'lg' | 'xl';
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  ...props 
}) => {
  const variants = {
    primary: 'bg-purple-600 text-white hover:bg-purple-700',
    sale: 'bg-emerald-500 text-white hover:bg-emerald-600',
    expense: 'bg-rose-500 text-white hover:bg-rose-600',
    outline: 'border-2 border-purple-600 text-purple-600 hover:bg-purple-50'
  };

  const sizes = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-4 py-2.5 text-base',
    lg: 'px-6 py-4 text-lg font-bold',
    xl: 'px-8 py-6 text-xl font-bold rounded-2xl shadow-lg'
  };

  return (
    <button 
      className={`rounded-xl transition-all active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2 ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

export const Card: React.FC<{ children: React.ReactNode; className?: string }> = ({ children, className = '' }) => (
  <div className={`bg-white rounded-2xl p-6 shadow-sm border border-slate-100 ${className}`}>
    {children}
  </div>
);

export const Input: React.FC<React.InputHTMLAttributes<HTMLInputElement> & { label?: string }> = ({ label, className = '', ...props }) => (
  <div className="flex flex-col gap-1.5 w-full">
    {label && <label className="text-sm font-semibold text-slate-700 ml-1">{label}</label>}
    <input 
      className={`w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 transition-all ${className}`}
      {...props}
    />
  </div>
);

export const StatBox: React.FC<{ label: string; value: string | number; color: string; icon: React.ReactNode }> = ({ label, value, color, icon }) => (
  <div className="flex-1 bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-4">
    <div className={`p-3 rounded-xl ${color} bg-opacity-10 text-white`}>
      <div className={`p-2 rounded-lg ${color}`}>
        {icon}
      </div>
    </div>
    <div>
      <p className="text-sm text-slate-500 font-medium">{label}</p>
      <p className="text-xl font-bold text-slate-900">{value}</p>
    </div>
  </div>
);

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { User, Business, Transaction, AppState, BusinessType } from './types';
import { Button, Card, Input, StatBox } from './components/UI';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  Cell
} from 'recharts';
import { 
  PlusCircle, 
  MinusCircle, 
  TrendingUp, 
  TrendingDown, 
  User as UserIcon, 
  Store, 
  Phone,
  ArrowRight,
  Sparkles,
  CheckCircle2
} from 'lucide-react';
import { getBusinessInsight } from './services/geminiService';

// --- Global State Store (Local Storage) ---
const STORAGE_KEY = 'digishe_app_data';

const initialState: AppState = {
  user: null,
  business: null,
  transactions: []
};

// --- Helper Functions ---
const formatDate = (date: Date) => date.toISOString().split('T')[0];

const getWeeklyData = (transactions: Transaction[]) => {
  const last7Days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return formatDate(d);
  }).reverse();

  return last7Days.map(date => {
    const daily = transactions.filter(t => t.date === date);
    return {
      date: new Date(date).toLocaleDateString('en-US', { weekday: 'short' }),
      sales: daily.filter(t => t.type === 'sale').reduce((acc, t) => acc + t.amount, 0),
      expenses: daily.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0)
    };
  });
};

// --- Auth Page ---
const AuthPage: React.FC<{ onLogin: (phone: string) => void }> = ({ onLogin }) => {
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [step, setStep] = useState<'phone' | 'otp'>('phone');

  const handleSendOTP = (e: React.FormEvent) => {
    e.preventDefault();
    if (phone.length >= 10) setStep('otp');
  };

  const handleVerify = (e: React.FormEvent) => {
    e.preventDefault();
    if (otp.length === 4) onLogin(phone);
  };

  return (
    <div className="min-h-screen bg-white flex flex-col p-6 items-center justify-center">
      <div className="w-full max-w-sm flex flex-col items-center gap-8">
        <div className="bg-purple-100 p-6 rounded-3xl">
          <Store size={48} className="text-purple-600" />
        </div>
        <div className="text-center">
          <h1 className="text-4xl font-extrabold text-slate-900 mb-2">DigiSHE</h1>
          <p className="text-slate-500 text-lg">Your business record buddy</p>
        </div>

        {step === 'phone' ? (
          <form onSubmit={handleSendOTP} className="w-full flex flex-col gap-4">
            <Input 
              label="Enter Phone Number" 
              type="tel" 
              placeholder="0123456789" 
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              className="text-center text-xl tracking-widest py-4"
              autoFocus
            />
            <Button size="xl" className="w-full mt-2" type="submit" disabled={phone.length < 10}>
              Send Code <ArrowRight size={20} />
            </Button>
          </form>
        ) : (
          <form onSubmit={handleVerify} className="w-full flex flex-col gap-4">
            <Input 
              label="Enter 4-Digit Code" 
              type="text" 
              placeholder="0000" 
              maxLength={4}
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
              className="text-center text-3xl font-bold tracking-[1rem] py-4"
              autoFocus
            />
            <Button size="xl" className="w-full mt-2" type="submit" disabled={otp.length !== 4}>
              Log In <CheckCircle2 size={20} />
            </Button>
            <button onClick={() => setStep('phone')} className="text-purple-600 font-medium">Use a different number</button>
          </form>
        )}
      </div>
    </div>
  );
};

// --- Onboarding Page ---
const OnboardingPage: React.FC<{ onComplete: (business: Business) => void }> = ({ onComplete }) => {
  const [name, setName] = useState('');
  const [type, setType] = useState<BusinessType>('Trading');
  const [location, setLocation] = useState('');

  const businessTypes: BusinessType[] = ['Food', 'Fashion', 'Trading', 'Production', 'Services'];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name) {
      onComplete({
        name,
        type,
        location,
        startDate: formatDate(new Date())
      });
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-6 flex flex-col">
      <div className="max-w-md mx-auto w-full py-8 space-y-8">
        <div>
          <h2 className="text-3xl font-extrabold text-slate-900">Setup Business</h2>
          <p className="text-slate-500">Just a few details to get started</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <Input 
            label="Business Name" 
            placeholder="e.g. Maria's Kitchen" 
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />

          <div className="flex flex-col gap-2">
            <label className="text-sm font-semibold text-slate-700 ml-1">Business Type</label>
            <div className="grid grid-cols-2 gap-2">
              {businessTypes.map((t) => (
                <button
                  key={t}
                  type="button"
                  onClick={() => setType(t)}
                  className={`p-3 rounded-xl border-2 text-sm font-bold transition-all ${
                    type === t 
                      ? 'border-purple-600 bg-purple-50 text-purple-600' 
                      : 'border-slate-200 bg-white text-slate-500'
                  }`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          <Input 
            label="Location (Optional)" 
            placeholder="e.g. Downtown Market" 
            value={location}
            onChange={(e) => setLocation(e.target.value)}
          />

          <Button size="xl" className="w-full" type="submit">
            Start Business <ArrowRight size={20} />
          </Button>
        </form>
      </div>
    </div>
  );
};

// --- Record Transaction Page ---
const RecordPage: React.FC<{ type: 'sale' | 'expense'; onSave: (amount: number) => void }> = ({ type, onSave }) => {
  const [amount, setAmount] = useState('');
  const [showSuccess, setShowSuccess] = useState(false);
  const navigate = useNavigate();

  const handleSave = () => {
    const val = parseFloat(amount);
    if (!isNaN(val) && val > 0) {
      onSave(val);
      setShowSuccess(true);
      setTimeout(() => navigate('/dashboard'), 1500);
    }
  };

  if (showSuccess) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6 text-center animate-in fade-in zoom-in duration-300">
        <div className={`p-8 rounded-full mb-6 ${type === 'sale' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
          <CheckCircle2 size={64} />
        </div>
        <h2 className="text-3xl font-bold mb-2">Saved Successfully!</h2>
        <p className="text-slate-500">Record added to your dashboard.</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col p-6">
      <header className="flex items-center gap-4 mb-8">
        <button onClick={() => navigate('/dashboard')} className="p-2 -ml-2 text-slate-400 hover:text-slate-600">
          <ArrowRight className="rotate-180" />
        </button>
        <h2 className="text-2xl font-bold">Record {type === 'sale' ? 'Sale' : 'Expense'}</h2>
      </header>

      <div className="flex-1 flex flex-col gap-8 max-w-md mx-auto w-full">
        <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100 text-center">
          <p className="text-slate-400 text-sm font-bold uppercase tracking-widest mb-2">Enter Amount</p>
          <div className="flex items-center justify-center gap-2">
            <span className="text-4xl font-bold text-slate-300">$</span>
            <input 
              type="number"
              inputMode="decimal"
              className="text-6xl font-extrabold w-full text-center focus:outline-none placeholder:text-slate-100"
              placeholder="0"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              autoFocus
            />
          </div>
          <p className="mt-6 text-slate-400 font-medium">Today: {new Date().toLocaleDateString()}</p>
        </div>

        <div className="grid grid-cols-3 gap-3">
          {[1,2,3,4,5,6,7,8,9,'.',0,'DEL'].map((k) => (
            <button
              key={k}
              onClick={() => {
                if (k === 'DEL') setAmount(prev => prev.slice(0, -1));
                else if (k === '.' && amount.includes('.')) return;
                else setAmount(prev => prev + k);
              }}
              className="h-20 rounded-2xl bg-white border border-slate-100 shadow-sm text-2xl font-bold active:bg-slate-50 flex items-center justify-center"
            >
              {k}
            </button>
          ))}
        </div>

        <Button 
          variant={type === 'sale' ? 'sale' : 'expense'} 
          size="xl" 
          className="w-full mt-auto" 
          onClick={handleSave}
          disabled={!amount || parseFloat(amount) <= 0}
        >
          {type === 'sale' ? <PlusCircle size={24} /> : <MinusCircle size={24} />}
          Save {type === 'sale' ? 'Sale' : 'Expense'}
        </Button>
      </div>
    </div>
  );
};

// --- Dashboard Component ---
const Dashboard: React.FC<{ 
  user: User; 
  business: Business; 
  transactions: Transaction[]; 
}> = ({ user, business, transactions }) => {
  const navigate = useNavigate();
  const [insight, setInsight] = useState<string>('Generating business tip...');

  const weeklyData = useMemo(() => getWeeklyData(transactions), [transactions]);

  const weeklyTotals = useMemo(() => {
    return {
      sales: transactions.filter(t => t.type === 'sale').reduce((acc, t) => acc + t.amount, 0),
      expenses: transactions.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0)
    };
  }, [transactions]);

  useEffect(() => {
    getBusinessInsight(business, transactions).then(setInsight);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="min-h-screen bg-slate-50 pb-32">
      {/* Header */}
      <div className="bg-purple-600 text-white p-6 pb-20 rounded-b-[3rem] shadow-xl">
        <div className="flex justify-between items-start mb-6">
          <div>
            <p className="text-purple-100 text-sm">Welcome back,</p>
            <h1 className="text-3xl font-bold">Hello {user.name} 👋</h1>
          </div>
          <div className="bg-white/20 p-2 rounded-full backdrop-blur-md">
            <UserIcon size={24} />
          </div>
        </div>

        <div className="bg-white/10 border border-white/20 rounded-2xl p-4 flex items-center gap-3 backdrop-blur-sm">
          <div className="bg-yellow-400 p-2 rounded-lg text-slate-900">
            <Sparkles size={20} />
          </div>
          <p className="text-sm font-medium leading-tight">{insight}</p>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="px-6 -mt-12 flex gap-4">
        <StatBox 
          label="Weekly Sales" 
          value={`$${weeklyTotals.sales.toLocaleString()}`} 
          color="bg-emerald-500"
          icon={<TrendingUp size={20} />}
        />
        <StatBox 
          label="Weekly Expenses" 
          value={`$${weeklyTotals.expenses.toLocaleString()}`} 
          color="bg-rose-500"
          icon={<TrendingDown size={20} />}
        />
      </div>

      {/* Main Chart */}
      <div className="p-6 space-y-6">
        <Card>
          <div className="flex justify-between items-center mb-6">
            <h3 className="font-bold text-slate-800 text-lg">Weekly Performance</h3>
            <div className="flex gap-4 text-xs font-bold uppercase text-slate-400">
              <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-emerald-500"></div> Sales</span>
              <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-rose-500"></div> Expenses</span>
            </div>
          </div>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={weeklyData} margin={{ top: 0, right: 0, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="date" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 600 }}
                  dy={10}
                />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 12 }} />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="sales" fill="#10b981" radius={[4, 4, 0, 0]} barSize={20} />
                <Bar dataKey="expenses" fill="#f43f5e" radius={[4, 4, 0, 0]} barSize={20} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>

        {/* Quick Recent List (Optional, but helps contextualize) */}
        <div className="flex flex-col gap-4">
           <h3 className="font-bold text-slate-800 text-lg px-2">Recent Records</h3>
           {transactions.length === 0 ? (
             <div className="text-center py-10 text-slate-400">
               No records yet. Start by adding a sale!
             </div>
           ) : (
             transactions.slice().reverse().slice(0, 5).map(t => (
               <div key={t.id} className="bg-white p-4 rounded-2xl flex items-center justify-between border border-slate-100 shadow-sm">
                 <div className="flex items-center gap-4">
                   <div className={`p-3 rounded-xl ${t.type === 'sale' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                     {t.type === 'sale' ? <TrendingUp size={20} /> : <TrendingDown size={20} />}
                   </div>
                   <div>
                     <p className="font-bold text-slate-800">{t.type === 'sale' ? 'Sale' : 'Expense'}</p>
                     <p className="text-xs text-slate-400">{new Date(t.date).toLocaleDateString()}</p>
                   </div>
                 </div>
                 <p className={`text-lg font-bold ${t.type === 'sale' ? 'text-emerald-600' : 'text-rose-600'}`}>
                   {t.type === 'sale' ? '+' : '-'}${t.amount.toLocaleString()}
                 </p>
               </div>
             ))
           )}
        </div>
      </div>

      {/* Primary Actions (Sticky Bottom) */}
      <div className="fixed bottom-0 inset-x-0 p-6 bg-gradient-to-t from-slate-50 via-slate-50 to-transparent flex gap-4">
        <Button variant="sale" size="lg" className="flex-1 shadow-lg shadow-emerald-200" onClick={() => navigate('/record/sale')}>
          <PlusCircle size={24} /> Record Sale
        </Button>
        <Button variant="expense" size="lg" className="flex-1 shadow-lg shadow-rose-200" onClick={() => navigate('/record/expense')}>
          <MinusCircle size={24} /> Record Expense
        </Button>
      </div>
    </div>
  );
};

// --- Main App Entry ---
const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : initialState;
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const handleLogin = (phone: string) => {
    setState(prev => ({
      ...prev,
      user: {
        phoneNumber: phone,
        name: 'Zooya', // Default for MVP
        hasCompletedOnboarding: !!prev.business
      }
    }));
  };

  const handleOnboarding = (business: Business) => {
    setState(prev => ({
      ...prev,
      business,
      user: prev.user ? { ...prev.user, hasCompletedOnboarding: true } : null
    }));
  };

  const addTransaction = (type: 'sale' | 'expense', amount: number) => {
    const newTransaction: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      userId: state.user?.phoneNumber || 'anon',
      type,
      amount,
      date: formatDate(new Date())
    };
    setState(prev => ({
      ...prev,
      transactions: [...prev.transactions, newTransaction]
    }));
  };

  const isAuthenticated = !!state.user;
  const isOnboarded = !!state.business;

  return (
    <HashRouter>
      <Routes>
        <Route path="/auth" element={
          !isAuthenticated ? <AuthPage onLogin={handleLogin} /> : <Navigate to="/onboarding" />
        } />

        <Route path="/onboarding" element={
          isAuthenticated ? (
            !isOnboarded ? <OnboardingPage onComplete={handleOnboarding} /> : <Navigate to="/dashboard" />
          ) : <Navigate to="/auth" />
        } />

        <Route path="/dashboard" element={
          isAuthenticated && isOnboarded ? (
            <Dashboard user={state.user!} business={state.business!} transactions={state.transactions} />
          ) : <Navigate to="/auth" />
        } />

        <Route path="/record/sale" element={
          isAuthenticated && isOnboarded ? (
            <RecordPage type="sale" onSave={(amt) => addTransaction('sale', amt)} />
          ) : <Navigate to="/auth" />
        } />

        <Route path="/record/expense" element={
          isAuthenticated && isOnboarded ? (
            <RecordPage type="expense" onSave={(amt) => addTransaction('expense', amt)} />
          ) : <Navigate to="/auth" />
        } />

        <Route path="*" element={<Navigate to={isAuthenticated ? (isOnboarded ? "/dashboard" : "/onboarding") : "/auth"} />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { User, Business, Transaction, AppState, BusinessType } from './types';
import { Button, Card, Input, StatBox } from './components/UI';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { 
  PlusCircle, 
  MinusCircle, 
  TrendingUp, 
  TrendingDown, 
  User as UserIcon, 
  Store, 
  ArrowRight,
  Sparkles,
  CheckCircle2,
  LogOut,
  ChevronLeft
} from 'lucide-react';
import { getBusinessInsight } from './services/geminiService';

// --- Global State Store (Local Storage) ---
const STORAGE_KEY = 'digishe_app_data_v2';

const initialState: AppState = {
  user: null,
  business: null,
  transactions: []
};

// --- Helper Functions ---
const formatDate = (date: Date) => date.toISOString().split('T')[0];

const getWeeklyData = (transactions: Transaction[]) => {
  const last7Days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return formatDate(d);
  }).reverse();

  return last7Days.map(date => {
    const daily = transactions.filter(t => t.date === date);
    return {
      date: new Date(date).toLocaleDateString('en-US', { weekday: 'short' }),
      fullDate: date,
      sales: daily.filter(t => t.type === 'sale').reduce((acc, t) => acc + t.amount, 0),
      expenses: daily.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0)
    };
  });
};

