// --- Main App Entry ---
const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : initialState;
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  const handleLogin = (phone: string) => {
    setState(prev => ({
      ...prev,
      user: {
        phoneNumber: phone,
        name: 'Zooya', // Mocked for MVP
        hasCompletedOnboarding: !!prev.business
      }
    }));
  };

  const handleLogout = () => {
    setState(prev => ({
      ...prev,
      user: null
    }));
  };

  const handleOnboarding = (business: Business) => {
    setState(prev => ({
      ...prev,
      business,
      user: prev.user ? { ...prev.user, hasCompletedOnboarding: true } : null
    }));
  };

  const addTransaction = (type: 'sale' | 'expense', amount: number) => {
    const newTransaction: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      userId: state.user?.phoneNumber || 'anon',
      type,
      amount,
      date: formatDate(new Date())
    };
    setState(prev => ({
      ...prev,
      transactions: [...prev.transactions, newTransaction]
    }));
  };

  const isAuthenticated = !!state.user;
  const isOnboarded = !!state.business;

  return (
    <HashRouter>
      <Routes>
        <Route path="/auth" element={
          !isAuthenticated ? <AuthPage onLogin={handleLogin} /> : <Navigate to="/onboarding" />
        } />

        <Route path="/onboarding" element={
          isAuthenticated ? (
            !isOnboarded ? <OnboardingPage onComplete={handleOnboarding} /> : <Navigate to="/dashboard" />
          ) : <Navigate to="/auth" />
        } />

        <Route path="/dashboard" element={
          isAuthenticated && isOnboarded ? (
            <Dashboard 
              user={state.user!} 
              business={state.business!} 
              transactions={state.transactions} 
              onLogout={handleLogout}
            />
          ) : <Navigate to="/auth" />
        } />

        <Route path="/record/sale" element={
          isAuthenticated && isOnboarded ? (
            <RecordPage type="sale" onSave={(amt) => addTransaction('sale', amt)} />
          ) : <Navigate to="/auth" />
        } />

        <Route path="/record/expense" element={
          isAuthenticated && isOnboarded ? (
            <RecordPage type="expense" onSave={(amt) => addTransaction('expense', amt)} />
          ) : <Navigate to="/auth" />
        } />

        <Route path="*" element={<Navigate to={isAuthenticated ? (isOnboarded ? "/dashboard" : "/onboarding") : "/auth"} />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

