        </div>
        <div className="text-center">
          <h1 className="text-4xl font-extrabold text-slate-900 mb-2">DigiSHE</h1>
          <p className="text-slate-500 text-lg">Empowering women business owners</p>
        </div>

        {step === 'phone' ? (
          <form onSubmit={handleSendOTP} className="w-full flex flex-col gap-4">
            <Input 
              label="Phone Number" 
              type="tel" 
              placeholder="Enter phone number" 
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              className="text-center text-xl tracking-widest py-4"
              autoFocus
            />
            <Button size="xl" className="w-full mt-2" type="submit" disabled={phone.length < 10}>
              Continue <ArrowRight size={20} />
            </Button>
          </form>
        ) : (
          <form onSubmit={handleVerify} className="w-full flex flex-col gap-4">
            <Input 
              label="Enter 4-Digit Code" 
