  business: null,
  transactions: []
};

// --- Helper Functions ---
const formatDate = (date: Date) => date.toISOString().split('T')[0];

const getWeeklyData = (transactions: Transaction[]) => {
  const last7Days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return formatDate(d);
  }).reverse();

  return last7Days.map(date => {
    const daily = transactions.filter(t => t.date === date);
    return {
      date: new Date(date).toLocaleDateString('en-US', { weekday: 'short' }),
      fullDate: date,
      sales: daily.filter(t => t.type === 'sale').reduce((acc, t) => acc + t.amount, 0),
      expenses: daily.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0)
    };
  });
};

// --- Auth Page ---
const AuthPage: React.FC<{ onLogin: (phone: string) => void }> = ({ onLogin }) => {
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [step, setStep] = useState<'phone' | 'otp'>('phone');

  const handleSendOTP = (e: React.FormEvent) => {
    e.preventDefault();
    if (phone.length >= 10) setStep('otp');
  };

  const handleVerify = (e: React.FormEvent) => {
    e.preventDefault();
    if (otp.length === 4) onLogin(phone);
  };

  return (
    <div className="min-h-screen bg-white flex flex-col p-6 items-center justify-center">
      <div className="w-full max-w-sm flex flex-col items-center gap-8">
        <div className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex items-center justify-center min-w-[120px] min-h-[120px]">
          <img 
            src="./logo.png" 
            alt="DigiSHE Logo" 
            className="h-24 w-24 object-contain block" 
            onError={(e) => (e.currentTarget.style.display = 'none')}
          />
        </div>
        <div className="text-center">
          <h1 className="text-4xl font-extrabold text-slate-900 mb-2">DigiSHE</h1>
          <p className="text-slate-500 text-lg">Empowering women business owners</p>
        </div>

        {step === 'phone' ? (
          <form onSubmit={handleSendOTP} className="w-full flex flex-col gap-4">
            <Input 
              label="Phone Number" 
              type="tel" 
              placeholder="Enter phone number" 
              value={phone}
