// --- Record Transaction Page ---
const RecordPage: React.FC<{ type: 'sale' | 'expense'; onSave: (amount: number) => void }> = ({ type, onSave }) => {
  const [amount, setAmount] = useState('');
  const [showSuccess, setShowSuccess] = useState(false);
  const navigate = useNavigate();

  const handleSave = () => {
    const val = parseFloat(amount);
    if (!isNaN(val) && val > 0) {
      onSave(val);
      setShowSuccess(true);
      setTimeout(() => navigate('/dashboard'), 1000);
    }
  };

  if (showSuccess) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6 text-center animate-in fade-in zoom-in duration-300">
        <div className={`p-8 rounded-full mb-6 ${type === 'sale' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
          <CheckCircle2 size={64} />
        </div>
        <h2 className="text-4xl font-black mb-2">{type === 'sale' ? 'Sale' : 'Expense'} Recorded!</h2>
        <p className="text-slate-500 text-lg">Heading back to your dashboard...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col p-6">
      <header className="flex items-center gap-4 mb-8">
        <button onClick={() => navigate('/dashboard')} className="p-3 bg-white rounded-xl shadow-sm text-slate-600">
          <ChevronLeft size={24} />
        </button>
        <h2 className="text-2xl font-bold">Record {type === 'sale' ? 'Sale' : 'Expense'}</h2>
      </header>

      <div className="flex-1 flex flex-col gap-8 max-w-md mx-auto w-full">
        <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100 text-center">
          <p className="text-slate-400 text-sm font-bold uppercase tracking-widest mb-2">Today's Amount</p>
          <div className="flex items-center justify-center gap-2">
            <span className="text-4xl font-bold text-slate-300">$</span>
            <input 
              type="number"
              inputMode="decimal"
              className="text-6xl font-extrabold w-full text-center focus:outline-none placeholder:text-slate-100"
              placeholder="0"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              autoFocus
            />
          </div>
          <p className="mt-6 text-slate-400 font-medium">Auto-filled: {new Date().toLocaleDateString()}</p>
        </div>

        <div className="grid grid-cols-3 gap-3">
          {[1,2,3,4,5,6,7,8,9,'.',0,'DEL'].map((k) => (
            <button
              key={k}
              type="button"
              onClick={() => {
                if (k === 'DEL') setAmount(prev => prev.slice(0, -1));
                else if (k === '.' && amount.includes('.')) return;
                else setAmount(prev => prev + String(k));
              }}
              className="h-20 rounded-2xl bg-white border border-slate-100 shadow-sm text-2xl font-bold active:bg-slate-100 flex items-center justify-center transition-colors"
            >
              {k}
            </button>
          ))}
        </div>

        <Button 
          variant={type === 'sale' ? 'sale' : 'expense'} 
          size="xl" 
          className="w-full mt-auto mb-4" 
          onClick={handleSave}
          disabled={!amount || parseFloat(amount) <= 0}
        >
          {type === 'sale' ? <PlusCircle size={24} /> : <MinusCircle size={24} />}
          Save {type === 'sale' ? 'Sale' : 'Expense'}
        </Button>
      </div>
    </div>
  );
};

