// --- Main App ---
export default function App() {
  const [state, setState] = useState<AppState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : initialState;
    } catch (e) {
      console.error("Failed to load state", e);
      return initialState;
    }
  });
  const [insight, setInsight] = useState("Keep up the great work!");

  // Persist state to local storage whenever it changes
  useEffect(() => {
    if (state.user) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    }
  }, [state]);

  // Refresh insight when transactions change
  useEffect(() => {
    if (state.business && state.transactions.length > 0) {
      getBusinessInsight(state.business, state.transactions).then(setInsight);
    }
  }, [state.business, state.transactions]);

  const handleAuth = (phoneNumber: string, name: string, isRegister: boolean) => {
    setState(prev => {
      const existingUser = prev.user?.phoneNumber === phoneNumber ? prev.user : null;
      return {
        ...prev,
        user: { 
          phoneNumber, 
          name: isRegister ? name : (existingUser?.name || ''), 
          hasCompletedOnboarding: isRegister ? false : (existingUser?.hasCompletedOnboarding || false)
        }
      };
    });
  };

  const handleOnboarding = (business: Business) => {
    setState(prev => ({
      ...prev,
      business,
      user: prev.user ? { ...prev.user, hasCompletedOnboarding: true } : null
    }));
  };

  const addTransaction = (type: 'sale' | 'expense', amount: number, category: string) => {
    const newTransaction: Transaction = {
      id: Math.random().toString(36).substr(2, 9),
      userId: state.user?.phoneNumber || 'anon',
      type,
      amount,
      category,
      date: formatDate(new Date())
    };
    setState(prev => ({
      ...prev,
      transactions: [...prev.transactions, newTransaction]
    }));
  };

  const handleLogout = () => {
    if (window.confirm("Are you sure you want to log out?")) {
      // Clear storage first to ensure it's gone
      localStorage.removeItem(STORAGE_KEY);
      localStorage.clear();
      // Set state to a fresh copy of initialState to trigger immediate redirect
      setState({ ...initialState });
    }
  };

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={
          !state.user ? <AuthPage onAuth={handleAuth} /> : (
            state.user.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <Navigate to="/onboarding" replace />
          )
        } />

        <Route path="/onboarding" element={
          state.user ? (
            state.user.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <OnboardingPage onComplete={handleOnboarding} />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="/dashboard" element={
          state.user?.hasCompletedOnboarding ? (
            <Dashboard state={state} onLogout={handleLogout} insight={insight} />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="/record/sale" element={
          state.user?.hasCompletedOnboarding ? (
            <RecordPage 
              type="sale" 
              onSave={(amt, cat) => addTransaction('sale', amt, cat)} 
              recentTransactions={state.transactions.filter(t => t.type === 'sale').slice().reverse().slice(0, 5)}
            />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="/record/expense" element={
          state.user?.hasCompletedOnboarding ? (
            <RecordPage 
              type="expense" 
              onSave={(amt, cat) => addTransaction('expense', amt, cat)} 
              recentTransactions={state.transactions.filter(t => t.type === 'expense').slice().reverse().slice(0, 5)}
            />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="*" element={<Navigate to={state.user ? (state.user.hasCompletedOnboarding ? "/dashboard" : "/onboarding") : "/login"} replace />} />
      </Routes>
    </HashRouter>
  );
}

