// --- Main App ---
export default function App() {
  const [state, setState] = useState<AppState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : initialState;
    } catch (e) {
      console.error("Failed to load state", e);
      return initialState;
    }
  });
  const [insight, setInsight] = useState("Keep up the great work!");
  const [isSyncing, setIsSyncing] = useState(false);

  // Persistence side-effect
  useEffect(() => {
    if (state.user) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    }
  }, [state]);

  // Gemini Insight side-effect
  useEffect(() => {
    if (state.business && state.transactions.length > 0) {
      getBusinessInsight(state.business, state.transactions).then(setInsight);
    }
  }, [state.business, state.transactions]);

  // Sync with Supabase on mount/login
  useEffect(() => {
    if (state.user && state.user.phoneNumber) {
      fetchDataFromSupabase(state.user.phoneNumber);
    }
  }, [state.user?.phoneNumber]);

  const fetchDataFromSupabase = async (phone: string) => {
    setIsSyncing(true);
    try {
      // 1. Get Profile
      const { data: profile } = await supabase
        .from('profiles')
        .select('*')
        .eq('phone', phone)
        .single();

      if (profile) {
        // 2. Get Business
        const { data: business } = await supabase
          .from('businesses')
          .select('*')
          .eq('user_id', profile.id)
          .single();

        // 3. Get Transactions
        let transactions: any[] = [];
        if (business) {
          const { data: txs } = await supabase
            .from('transactions')
            .select('*')
            .eq('business_id', business.id);
          transactions = txs || [];
        }

        setState(prev => ({
          ...prev,
          user: { 
            phoneNumber: phone, 
            name: profile.name, 
            hasCompletedOnboarding: profile.has_completed_onboarding 
          },
          business: business ? {
            name: business.name,
            type: business.type,
            startDate: business.start_date
          } : null,
          transactions: transactions.map(t => ({
            id: t.id,
            userId: phone,
            type: t.type,
            amount: t.amount,
            category: t.category,
            date: t.date
          }))
        }));
      }
    } catch (err) {
      console.error("Supabase sync error:", err);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAuth = async (phoneNumber: string, name: string, isRegister: boolean) => {
    // Upsert Profile
    const { data: profile, error } = await supabase
      .from('profiles')
      .upsert({ 
        phone: phoneNumber, 
        name: isRegister ? name : undefined 
      }, { onConflict: 'phone' })
      .select()
      .single();

    if (profile) {
      setState(prev => ({
        ...prev,
        user: { 
          phoneNumber, 
          name: profile.name || name, 
          hasCompletedOnboarding: profile.has_completed_onboarding
        }
      }));
    }
  };

  const handleOnboarding = async (business: Business) => {
    if (!state.user) return;

    // 1. Find user profile id
    const { data: profile } = await supabase
      .from('profiles')
      .select('id')
      .eq('phone', state.user.phoneNumber)
      .single();

    if (profile) {
      // 2. Create Business
      const { data: newBusiness } = await supabase
        .from('businesses')
        .insert({
          user_id: profile.id,
          name: business.name,
          type: business.type,
          start_date: business.startDate
        })
        .select()
        .single();

      // 3. Update profile status
      await supabase
        .from('profiles')
        .update({ has_completed_onboarding: true })
        .eq('id', profile.id);

      setState(prev => ({
        ...prev,
        business,
        user: prev.user ? { ...prev.user, hasCompletedOnboarding: true } : null
      }));
    }
  };

  const addTransaction = async (type: 'sale' | 'expense', amount: number, category: string) => {
    if (!state.user || !state.business) return;

    // Local optimistic update
    const tempId = Math.random().toString(36).substr(2, 9);
    const newTx: Transaction = {
      id: tempId,
      userId: state.user.phoneNumber,
      type,
      amount,
      category,
      date: formatDate(new Date())
    };

    setState(prev => ({
      ...prev,
      transactions: [...prev.transactions, newTx]
    }));

    // Persist to Supabase
    const { data: profile } = await supabase
      .from('profiles')
      .select('id')
      .eq('phone', state.user.phoneNumber)
      .single();

    if (profile) {
      const { data: biz } = await supabase
        .from('businesses')
        .select('id')
        .eq('user_id', profile.id)
        .single();

      if (biz) {
        await supabase.from('transactions').insert({
          business_id: biz.id,
          type,
          amount,
          category,
          date: newTx.date
        });
      }
    }
  };

  const handleLogout = () => {
    if (window.confirm("Are you sure you want to log out?")) {
      localStorage.removeItem(STORAGE_KEY);
      localStorage.clear();
      setState({ ...initialState });
    }
  };

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={
          !state.user ? <AuthPage onAuth={handleAuth} /> : (
            state.user.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <Navigate to="/onboarding" replace />
          )
        } />

        <Route path="/onboarding" element={
          state.user ? (
            state.user.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <OnboardingPage onComplete={handleOnboarding} />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="/dashboard" element={
          state.user?.hasCompletedOnboarding ? (
            <Dashboard state={state} onLogout={handleLogout} insight={insight} />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="/record/sale" element={
          state.user?.hasCompletedOnboarding ? (
            <RecordPage 
              type="sale" 
              onSave={(amt, cat) => addTransaction('sale', amt, cat)} 
              recentTransactions={state.transactions.filter(t => t.type === 'sale').slice().reverse().slice(0, 5)}
            />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="/record/expense" element={
          state.user?.hasCompletedOnboarding ? (
            <RecordPage 
              type="expense" 
              onSave={(amt, cat) => addTransaction('expense', amt, cat)} 
              recentTransactions={state.transactions.filter(t => t.type === 'expense').slice().reverse().slice(0, 5)}
            />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="*" element={<Navigate to={state.user ? (state.user.hasCompletedOnboarding ? "/dashboard" : "/onboarding") : "/login"} replace />} />
      </Routes>
      {isSyncing && (
        <div className="fixed top-4 right-4 bg-white/80 backdrop-blur px-3 py-1 rounded-full text-[10px] font-bold text-slate-400 shadow-sm border border-slate-100 flex items-center gap-2">
          <Loader2 size={10} className="animate-spin" /> SYNCING BACKEND
        </div>
      )}
    </HashRouter>
  );
}

