                  recentTransactions.map(t => (
                    <tr key={t.id} className="hover:bg-slate-50/50">
                      <td className="px-4 py-3 font-medium text-slate-700">{t.category}</td>
                      <td className={`px-4 py-3 text-right font-bold ${type === 'sale' ? 'text-emerald-600' : 'text-rose-600'}`}>
                        ${t.amount.toLocaleString()}
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={2} className="px-4 py-8 text-center text-slate-400 italic">
                      No recent {type}s found
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>

        {/* Input Form */}
        <Card className="space-y-6">
          <SearchableDropdown 
            label="Category"
            placeholder={`Select ${type} category`}
            options={categories}
            value={category}
            onChange={setCategory}
          />

          <div className="space-y-1.5">
            <label className="text-sm font-semibold text-slate-700 ml-1">Amount</label>
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">$</span>
              <input 
                type="number" 
                inputMode="decimal"
                className="w-full pl-8 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/20 text-2xl font-black text-slate-900"
                placeholder="0.00"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
              />
            </div>
          </div>

          <Button 
            size="xl" 
            variant={type === 'sale' ? 'sale' : 'expense'} 
            className="w-full shadow-xl"
            onClick={handleSave}
            disabled={!amount || parseFloat(amount) <= 0 || !category}
          >
            {type === 'sale' ? <PlusCircle size={24} /> : <MinusCircle size={24} />}
            Save {type === 'sale' ? 'Sale' : 'Expense'}
          </Button>
        </Card>
      </main>
    </div>
  );
};

// --- Dashboard Component ---
const Dashboard: React.FC<{ 
  state: AppState; 
  onLogout: () => void;
  insight: string;
}> = ({ state, onLogout, insight }) => {
  const navigate = useNavigate();

  const stats = useMemo(() => {
    const sales = state.transactions.filter(t => t.type === 'sale').reduce((acc, t) => acc + t.amount, 0);
    const expenses = state.transactions.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0);
    return { sales, expenses, balance: sales - expenses };
  }, [state.transactions]);

  const chartData = useMemo(() => getWeeklyData(state.transactions), [state.transactions]);

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white p-6 border-b border-slate-100 sticky top-0 z-10">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="bg-purple-600 p-2 rounded-xl">
              <Store className="text-white" size={20} />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-900 leading-tight">{state.business?.name}</h1>
              <p className="text-xs font-semibold text-purple-600 uppercase tracking-wider">{state.business?.type}</p>
            </div>
          </div>
          <button 
            onClick={onLogout} 
            className="p-2 text-slate-400 hover:text-rose-500 transition-all active:scale-90"
            aria-label="Logout"
          >
            <LogOut size={24} />
          </button>
        </div>
      </header>

      <main className="p-6 max-w-4xl mx-auto space-y-6">
        {/* Insight Card with Gemini output */}
        <Card className="bg-gradient-to-br from-purple-600 to-indigo-700 border-none text-white overflow-hidden relative">
          <Sparkles className="absolute -right-4 -top-4 text-white/10 w-32 h-32" />
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-2">
              <Sparkles size={18} className="text-yellow-300" />
              <p className="text-sm font-bold text-purple-100 uppercase tracking-widest">Business Tip</p>
            </div>
            <p className="text-lg font-medium leading-relaxed italic">
              "{insight}"
            </p>
          </div>
        </Card>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <StatBox 
            label="Total Sales" 
            value={`$${stats.sales.toLocaleString()}`} 
            color="bg-emerald-500" 
            icon={<TrendingUp size={20} />} 
          />
          <StatBox 
            label="Expenses" 
            value={`$${stats.expenses.toLocaleString()}`} 
            color="bg-rose-500" 
            icon={<TrendingDown size={20} />} 
          />
          <StatBox 
            label="Balance" 
            value={`$${stats.balance.toLocaleString()}`} 
            color="bg-purple-500" 
            icon={<UserIcon size={20} />} 
          />
        </div>

        {/* Chart */}
        <Card className="flex flex-col gap-4">
          <h3 className="font-bold text-slate-800">Weekly Performance</h3>
          <div className="h-[250px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}}
                />
                <Bar dataKey="sales" fill="#10b981" radius={[4, 4, 0, 0]} />
                <Bar dataKey="expenses" fill="#f43f5e" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>

        {/* History */}
        <div className="space-y-4">
          <h3 className="font-bold text-slate-800 px-1">Recent Transactions</h3>
          <div className="space-y-3">
            {state.transactions.length === 0 ? (
              <p className="text-center py-8 text-slate-400 italic">No transactions yet. Start recording!</p>
            ) : (
              state.transactions.slice().reverse().slice(0, 5).map(t => (
                <div key={t.id} className="flex items-center justify-between bg-white p-4 rounded-xl border border-slate-100">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-lg ${t.type === 'sale' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                      {t.type === 'sale' ? <PlusCircle size={18} /> : <MinusCircle size={18} />}
                    </div>
                    <div>
                      <p className="font-bold text-slate-800 capitalize">{t.category || t.type}</p>
                      <p className="text-xs text-slate-400">{new Date(t.date).toLocaleDateString()}</p>
                    </div>
                  </div>
                  <p className={`font-bold ${t.type === 'sale' ? 'text-emerald-600' : 'text-rose-600'}`}>
                    {t.type === 'sale' ? '+' : '-'}${t.amount.toLocaleString()}
                  </p>
                </div>
              ))
            )}
          </div>
        </div>
      </main>

      {/* Action Bar */}
      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 p-4 pb-8 safe-area-bottom">
        <div className="max-w-4xl mx-auto grid grid-cols-2 gap-4">
          <Button variant="sale" size="lg" className="w-full" onClick={() => navigate('/record/sale')}>
            <PlusCircle size={20} /> Record Sale
          </Button>
          <Button variant="expense" size="lg" className="w-full" onClick={() => navigate('/record/expense')}>
            <MinusCircle size={20} /> Record Expense
          </Button>
        </div>
      </div>
    </div>
  );
};

// --- Auth Page ---
const AuthPage: React.FC<{ onAuth: (phone: string, name: string, isRegister: boolean) => Promise<void> }> = ({ onAuth }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [step, setStep] = useState<'input' | 'otp'>('input');
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [otp, setOtp] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleContinue = async () => {
    if (mode === 'register' && !name) {
      setError('Please enter your full name');
      return;
    }
    if (!phone) {
      setError('Please enter your phone number');
      return;
    }

    setIsLoading(true);
    setError('');

    try {
      // Check if user exists in Supabase
      const { data, error: fetchError } = await supabase
        .from('profiles')
        .select('id')
        .eq('phone', phone)
        .maybeSingle();

      if (fetchError) throw fetchError;

      if (mode === 'login' && !data) {
        setError('No account found with this phone number. Please register.');
        setIsLoading(false);
        return;
      }

      if (mode === 'register' && data) {
        setError('An account with this phone number already exists. Please login.');
        setIsLoading(false);
        return;
      }

      setStep('otp');
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Something went wrong. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifyOtp = async () => {
    if (otp === '1234') {
      setIsLoading(true);
      try {
        await onAuth(phone, name, mode === 'register');
      } catch (err: any) {
        setError(err.message || 'Verification failed');
      } finally {
        setIsLoading(false);
      }
    } else {
      setError('Invalid code. Try "1234"');
    }
  };

  return (
    <div className="min-h-screen bg-purple-600 flex flex-col items-center justify-center p-6 text-white">
      <div className="w-full max-w-md space-y-8 text-center">
        <div className="flex flex-col items-center gap-4">
          <div className="bg-white p-4 rounded-3xl shadow-xl">
            <Store className="text-purple-600 w-12 h-12" />
          </div>
          <h1 className="text-4xl font-black">DigiShe</h1>
          <p className="text-purple-100 text-lg font-medium">Digital bookkeeping for women entrepreneurs</p>
        </div>

        <Card className="p-8 space-y-6 text-slate-900">
          {step === 'input' ? (
            <div className="space-y-6">
              <h2 className="text-2xl font-bold text-slate-800">{mode === 'login' ? 'Welcome Back' : 'Create Account'}</h2>

              <div className="space-y-4">
                {mode === 'register' && (
                  <Input 
                    label="Full Name" 
                    placeholder="Enter your name" 
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    disabled={isLoading}
                  />
                )}
                <Input 
                  label="Phone Number" 
                  type="tel"
                  placeholder="e.g. +254 700 000 000" 
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  disabled={isLoading}
                />
              </div>

              {error && (
                <div className="flex items-center gap-2 bg-rose-50 text-rose-600 p-3 rounded-xl text-sm font-medium">
                  <AlertCircle size={16} />
                  <span>{error}</span>
                </div>
              )}

              <Button 
                size="xl" 
                className="w-full" 
                onClick={handleContinue}
                disabled={isLoading}
              >
                {isLoading ? <Loader2 className="animate-spin" size={24} /> : <>Continue <ArrowRight size={20} /></>}
              </Button>

              <div className="pt-2">
                <button 
                  onClick={() => {
                    setMode(mode === 'login' ? 'register' : 'login');
                    setError('');
                  }}
                  disabled={isLoading}
                  className="text-purple-600 font-bold hover:underline disabled:opacity-50"
                >
                  {mode === 'login' ? "Don't have an account? Register" : "Already have an account? Sign in"}
                </button>
              </div>
            </div>
          ) : (
            <div className="space-y-6 animate-in slide-in-from-right duration-300">
              <div className="flex justify-center">
                <div className="bg-purple-50 p-3 rounded-full text-purple-600">
                  <ShieldCheck size={40} />
                </div>
              </div>

              <div className="space-y-2">
                <h2 className="text-2xl font-bold text-slate-800 text-center">Enter Code</h2>
                <p className="text-slate-500 text-sm text-center">
                  We've sent a code to <span className="font-bold text-slate-700">{phone}</span>
                </p>
                <div className="bg-amber-50 border border-amber-200 p-2 rounded-lg text-amber-800 text-xs font-medium text-center">
                   MVP SAMPLE: Use code <span className="font-bold">1234</span>
                </div>
              </div>

              <div className="flex justify-center gap-2">
                <input 
                  type="text" 
                  maxLength={4}
                  className="w-full max-w-[180px] text-center text-4xl font-black tracking-[0.5em] py-4 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/20"
                  value={otp}
                  onChange={(e) => setOtp(e.target.value)}
                  disabled={isLoading}
                  autoFocus
                />
              </div>

              {error && <p className="text-rose-500 text-sm font-medium text-center">{error}</p>}

              <Button 
                size="xl" 
                className="w-full" 
                onClick={handleVerifyOtp}
                disabled={otp.length < 4 || isLoading}
              >
                {isLoading ? <Loader2 className="animate-spin" size={24} /> : 'Verify & Login'}
              </Button>

              <button 
                onClick={() => setStep('input')}
                disabled={isLoading}
                className="text-slate-400 font-medium hover:text-slate-600 flex items-center justify-center gap-1 w-full"
              >
                <ChevronLeft size={16} /> Edit Phone Number
              </button>
            </div>
          )}
          <p className="text-xs text-slate-400 text-center">By continuing, you agree to our Terms of Service.</p>
        </Card>
      </div>
    </div>
  );
};

// --- Onboarding Page ---
const OnboardingPage: React.FC<{ onComplete: (business: Business) => Promise<void> }> = ({ onComplete }) => {
  const [name, setName] = useState('');
  const [type, setType] = useState<BusinessType>('Food');
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState('');

  const businessTypes: BusinessType[] = ['Food', 'Fashion', 'Trading', 'Production', 'Services'];

  const handleSubmit = async () => {
    setIsSaving(true);
    setError('');
    try {
      await onComplete({ name, type, startDate: new Date().toISOString() });
    } catch (err: any) {
      setError(err.message || 'Failed to save business info');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-6 flex flex-col items-center justify-center">
      <div className="w-full max-w-md space-y-8">
        <div className="text-center space-y-2">
          <h2 className="text-3xl font-black text-slate-900">Tell us about your business</h2>
          <p className="text-slate-500">Let's set up your digital ledger</p>
        </div>

        <Card className="space-y-6">
          <Input 
            label="Business Name" 
            placeholder="e.g. Mama's Kitchen" 
            value={name}
            onChange={(e) => setName(e.target.value)}
            disabled={isSaving}
          />

          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-700 ml-1">Business Category</label>
            <div className="grid grid-cols-2 gap-2">
              {businessTypes.map(t => (
                <button
                  key={t}
                  type="button"
                  disabled={isSaving}
                  onClick={() => setType(t)}
                  className={`px-4 py-3 rounded-xl border text-sm font-bold transition-all ${type === t ? 'bg-purple-600 border-purple-600 text-white shadow-lg' : 'bg-white border-slate-200 text-slate-600 hover:border-purple-300'}`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          {error && <p className="text-rose-500 text-sm font-medium text-center">{error}</p>}

          <Button 
            size="xl" 
            className="w-full" 
            onClick={handleSubmit}
            disabled={!name || isSaving}
          >
            {isSaving ? <Loader2 className="animate-spin" /> : <>Create My Business <ArrowRight size={20} /></>}
          </Button>
        </Card>
      </div>
    </div>
  );
};

// --- Main App ---
export default function App() {
  const [state, setState] = useState<AppState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : initialState;
    } catch (e) {
      console.error("Failed to load state", e);
      return initialState;
    }
  });
  const [insight, setInsight] = useState("Keep up the great work!");
  const [isSyncing, setIsSyncing] = useState(false);

  // Persistence side-effect
  useEffect(() => {
    if (state.user) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    }
  }, [state]);

  // Gemini Insight side-effect
  useEffect(() => {
    if (state.business && state.transactions.length > 0) {
      getBusinessInsight(state.business, state.transactions).then(setInsight);
    }
  }, [state.business, state.transactions]);

  // Sync with Supabase on mount/login
  useEffect(() => {
    if (state.user && state.user.phoneNumber) {
      fetchDataFromSupabase(state.user.phoneNumber);
    }
  }, [state.user?.phoneNumber]);

  const fetchDataFromSupabase = async (phone: string) => {
    setIsSyncing(true);
    try {
      const { data: profile } = await supabase
        .from('profiles')
        .select('*')
        .eq('phone', phone)
        .single();

      if (profile) {
        const { data: business } = await supabase
          .from('businesses')
          .select('*')
          .eq('user_id', profile.id)
          .maybeSingle();

        let transactions: any[] = [];
        if (business) {
          const { data: txs } = await supabase
            .from('transactions')
            .select('*')
            .eq('business_id', business.id);
          transactions = txs || [];
        }

        setState(prev => ({
          ...prev,
          user: { 
            phoneNumber: phone, 
            name: profile.name, 
            hasCompletedOnboarding: profile.has_completed_onboarding 
          },
          business: business ? {
            name: business.name,
            type: business.type,
            startDate: business.start_date
          } : null,
          transactions: transactions.map(t => ({
            id: t.id,
            userId: phone,
            type: t.type,
            amount: t.amount,
            category: t.category,
            date: t.date
          }))
        }));
      }
    } catch (err) {
      console.error("Supabase sync error:", err);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAuth = async (phoneNumber: string, name: string, isRegister: boolean) => {
    let profileData;

    if (isRegister) {
      const { data, error } = await supabase
        .from('profiles')
        .insert({ 
          phone: phoneNumber, 
          name: name,
          has_completed_onboarding: false
        })
        .select()
        .single();

      if (error) throw error;
      profileData = data;
    } else {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('phone', phoneNumber)
        .single();

      if (error) throw error;
      profileData = data;
    }

    if (profileData) {
      setState(prev => ({
        ...prev,
        user: { 
          phoneNumber, 
          name: profileData.name || name, 
          hasCompletedOnboarding: profileData.has_completed_onboarding
        }
      }));
    }
  };

  const handleOnboarding = async (business: Business) => {
    if (!state.user) return;

    const { data: profile } = await supabase
      .from('profiles')
      .select('id')
      .eq('phone', state.user.phoneNumber)
      .single();

    if (profile) {
      const { error: bizError } = await supabase
        .from('businesses')
        .insert({
          user_id: profile.id,
          name: business.name,
          type: business.type,
          start_date: business.startDate
        });

      if (bizError) throw bizError;

      const { error: profileError } = await supabase
        .from('profiles')
        .update({ has_completed_onboarding: true })
        .eq('id', profile.id);

      if (profileError) throw profileError;

      setState(prev => ({
        ...prev,
        business,
        user: prev.user ? { ...prev.user, hasCompletedOnboarding: true } : null
      }));
    }
  };

  const addTransaction = async (type: 'sale' | 'expense', amount: number, category: string) => {
    if (!state.user || !state.business) return;

    const tempId = Math.random().toString(36).substr(2, 9);
    const dateStr = formatDate(new Date());
    const newTx: Transaction = {
      id: tempId,
      userId: state.user.phoneNumber,
      type,
      amount,
      category,
      date: dateStr
    };

    setState(prev => ({
      ...prev,
      transactions: [...prev.transactions, newTx]
    }));

    const { data: profile } = await supabase
      .from('profiles')
      .select('id')
      .eq('phone', state.user.phoneNumber)
      .single();

    if (profile) {
      const { data: biz } = await supabase
        .from('businesses')
        .select('id')
        .eq('user_id', profile.id)
        .single();

      if (biz) {
        await supabase.from('transactions').insert({
          business_id: biz.id,
          type,
          amount,
          category,
          date: dateStr
        });
      }
    }
  };

  const handleLogout = () => {
    if (window.confirm("Are you sure you want to log out?")) {
      localStorage.removeItem(STORAGE_KEY);
      localStorage.clear();
      setState({ ...initialState });
    }
  };

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={
          !state.user ? <AuthPage onAuth={handleAuth} /> : (
            state.user.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <Navigate to="/onboarding" replace />
          )
        } />

        <Route path="/onboarding" element={
          state.user ? (
            state.user.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <OnboardingPage onComplete={handleOnboarding} />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="/dashboard" element={
          state.user?.hasCompletedOnboarding ? (
            <Dashboard state={state} onLogout={handleLogout} insight={insight} />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="/record/sale" element={
          state.user?.hasCompletedOnboarding ? (
            <RecordPage 
              type="sale" 
              onSave={(amt, cat) => addTransaction('sale', amt, cat)} 
              recentTransactions={state.transactions.filter(t => t.type === 'sale').slice().reverse().slice(0, 5)}
            />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="/record/expense" element={
          state.user?.hasCompletedOnboarding ? (
            <RecordPage 
              type="expense" 
              onSave={(amt, cat) => addTransaction('expense', amt, cat)} 
              recentTransactions={state.transactions.filter(t => t.type === 'expense').slice().reverse().slice(0, 5)}
            />
          ) : <Navigate to="/login" replace />
        } />

        <Route path="*" element={<Navigate to={state.user ? (state.user.hasCompletedOnboarding ? "/dashboard" : "/onboarding") : "/login"} replace />} />
      </Routes>
      {isSyncing && (
        <div className="fixed top-4 right-4 bg-white/80 backdrop-blur px-3 py-1 rounded-full text-[10px] font-bold text-slate-400 shadow-sm border border-slate-100 flex items-center gap-2">
          <Loader2 size={10} className="animate-spin" /> SYNCING BACKEND
        </div>
      )}
    </HashRouter>
  );
}

