const SQL_SETUP = `-- 1. Profiles Table
CREATE TABLE public.profiles (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  phone text UNIQUE NOT NULL,
  name text,
  has_completed_onboarding boolean DEFAULT false,
  created_at timestamp with time zone DEFAULT now()
);

-- 2. Businesses Table
CREATE TABLE public.businesses (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
  name text NOT NULL,
  type text NOT NULL,
  start_date timestamp with time zone NOT NULL,
  created_at timestamp with time zone DEFAULT now()
);

-- 3. Transactions Table
CREATE TABLE public.transactions (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  business_id uuid REFERENCES public.businesses(id) ON DELETE CASCADE,
  type text CHECK (type IN ('sale', 'expense')),
  amount numeric NOT NULL,
  category text,
  date date NOT NULL,
  created_at timestamp with time zone DEFAULT now()
);

-- Enable RLS (Optional for MVP, but good practice)
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.businesses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;

-- Allow public access for now (Anonymous Key access)
CREATE POLICY "Public Profiles Access" ON public.profiles FOR ALL USING (true);
CREATE POLICY "Public Businesses Access" ON public.businesses FOR ALL USING (true);
CREATE POLICY "Public Transactions Access" ON public.transactions FOR ALL USING (true);`;

// --- Helper Functions ---
const formatDate = (date: Date) => date.toISOString().split('T')[0];

const getWeeklyData = (transactions: Transaction[]) => {
  const last7Days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return formatDate(d);
  }).reverse();

  return last7Days.map(date => {
    const daily = transactions.filter(t => t.date === date);
    return {
      date: new Date(date).toLocaleDateString('en-US', { weekday: 'short' }),
      fullDate: date,
      sales: daily.filter(t => t.type === 'sale').reduce((acc, t) => acc + t.amount, 0),
      expenses: daily.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0)
    };
  });
};

