const AuthPage: React.FC<{ 
  onAuth: (phone: string, name: string, isRegister: boolean) => Promise<void>;
  onMissingTables: () => void;
}> = ({ onAuth, onMissingTables }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [step, setStep] = useState<'input' | 'otp'>('input');
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [otp, setOtp] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleContinue = async () => {
    if (mode === 'register' && !name) {
      setError('Please enter your full name');
      return;
    }
    if (!phone) {
      setError('Please enter your phone number');
      return;
    }

    setIsLoading(true);
    setError('');

    try {
      const { data, error: fetchError } = await supabase
        .from('profiles')
        .select('id')
        .eq('phone', phone)
        .maybeSingle();

      if (fetchError) {
        if (fetchError.message.includes('Could not find the table')) {
          onMissingTables();
          throw new Error('Database tables not found. Showing setup guide...');
        }
        throw fetchError;
      }

      if (mode === 'login' && !data) {
        setError('No account found. Please register first.');
        setIsLoading(false);
        return;
      }

      if (mode === 'register' && data) {
        setError('Phone number already registered. Please login.');
        setIsLoading(false);
        return;
      }

      setStep('otp');
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Database error. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifyOtp = async () => {
    if (otp === '1234') {
      setIsLoading(true);
      try {
        await onAuth(phone, name, mode === 'register');
      } catch (err: any) {
        setError(err.message || 'Verification failed');
      } finally {
        setIsLoading(false);
      }
    } else {
      setError('Invalid code. Try "1234"');
    }
  };

  return (
    <div className="min-h-screen bg-purple-600 flex flex-col items-center justify-center p-6 text-white">
      <div className="w-full max-w-md space-y-8 text-center">
        <div className="flex flex-col items-center gap-4">
          <div className="bg-white p-4 rounded-3xl shadow-xl">
            <Store className="text-purple-600 w-12 h-12" />
          </div>
          <h1 className="text-4xl font-black">DigiShe</h1>
          <p className="text-purple-100 text-lg font-medium">Digital bookkeeping for women entrepreneurs</p>
        </div>

        <Card className="p-8 space-y-6 text-slate-900">
          {step === 'input' ? (
            <div className="space-y-6">
              <h2 className="text-2xl font-bold text-slate-800">{mode === 'login' ? 'Welcome Back' : 'Create Account'}</h2>

              <div className="space-y-4">
                {mode === 'register' && (
                  <Input 
                    label="Full Name" 
                    placeholder="Enter your name" 
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    disabled={isLoading}
                  />
                )}
                <Input 
                  label="Phone Number" 
                  type="tel"
                  placeholder="e.g. +254 700 000 000" 
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  disabled={isLoading}
                />
              </div>

              {error && (
                <div className="flex items-start gap-2 bg-rose-50 text-rose-600 p-3 rounded-xl text-xs font-medium text-left leading-relaxed">
                  <AlertCircle size={16} className="shrink-0 mt-0.5" />
                  <span>{error}</span>
                </div>
              )}

              <Button 
                size="xl" 
                className="w-full" 
                onClick={handleContinue}
                disabled={isLoading}
              >
                {isLoading ? <Loader2 className="animate-spin" size={24} /> : <>Continue <ArrowRight size={20} /></>}
              </Button>

              <div className="pt-2">
                <button 
                  onClick={() => {
                    setMode(mode === 'login' ? 'register' : 'login');
                    setError('');
                  }}
                  disabled={isLoading}
                  className="text-purple-600 font-bold hover:underline disabled:opacity-50"
                >
                  {mode === 'login' ? "Don't have an account? Register" : "Already have an account? Sign in"}
                </button>
              </div>
            </div>
          ) : (
            <div className="space-y-6 animate-in slide-in-from-right duration-300">
              <div className="flex justify-center">
                <div className="bg-purple-50 p-3 rounded-full text-purple-600">
                  <ShieldCheck size={40} />
                </div>
              </div>

              <div className="space-y-2">
                <h2 className="text-2xl font-bold text-slate-800 text-center">Enter Code</h2>
                <p className="text-slate-500 text-sm text-center">
                  We've sent a code to <span className="font-bold text-slate-700">{phone}</span>
                </p>
                <div className="bg-amber-50 border border-amber-200 p-2 rounded-lg text-amber-800 text-xs font-medium text-center">
                   MVP SAMPLE: Use code <span className="font-bold">1234</span>
                </div>
              </div>

              <div className="flex justify-center gap-2">
                <input 
                  type="text" 
                  maxLength={4}
                  className="w-full max-w-[180px] text-center text-4xl font-black tracking-[0.5em] py-4 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/20"
                  value={otp}
                  onChange={(e) => setOtp(e.target.value)}
                  disabled={isLoading}
                  autoFocus
                />
              </div>

              {error && <p className="text-rose-500 text-sm font-medium text-center">{error}</p>}

              <Button 
                size="xl" 
                className="w-full" 
                onClick={handleVerifyOtp}
                disabled={otp.length < 4 || isLoading}
              >
                {isLoading ? <Loader2 className="animate-spin" size={24} /> : 'Verify & Login'}
              </Button>

              <button 
                onClick={() => setStep('input')}
                disabled={isLoading}
                className="text-slate-400 font-medium hover:text-slate-600 flex items-center justify-center gap-1 w-full"
              >
                <ChevronLeft size={16} /> Edit Phone Number
              </button>
            </div>
          )}
          <p className="text-xs text-slate-400 text-center">By continuing, you agree to our Terms of Service.</p>
        </Card>
      </div>
