const getSupabaseConfig = () => {
  const env = (window as any).process?.env || {};

  const url = env.SUPABASE_URL || localStorage.getItem(STORAGE_KEYS.URL);
  const key = env.SUPABASE_ANON_KEY || localStorage.getItem(STORAGE_KEYS.KEY);

  return {
    url,
    key,
    isPlaceholder: !env.SUPABASE_URL && !env.SUPABASE_ANON_KEY && !localStorage.getItem(STORAGE_KEYS.URL)
  };
};

const config = getSupabaseConfig();

// Initialize the client. We use a function-based approach for re-initialization if needed.
export const supabase = createClient(
  config.url || 'https://placeholder.supabase.co', 
  config.key || 'placeholder-key'
);

/**
 * Checks if the Supabase configuration is valid (not placeholders)
 */
export const isSupabaseConfigured = () => {
  const { url, key, isPlaceholder } = getSupabaseConfig();
  return !isPlaceholder && url && url !== 'https://placeholder.supabase.co' && key && key !== 'placeholder-key';
};

/**
 * Saves configuration to localStorage and reloads to apply changes
 */
export const saveSupabaseConfig = (url: string, key: string) => {
  localStorage.setItem(STORAGE_KEYS.URL, url);
  localStorage.setItem(STORAGE_KEYS.KEY, key);
  window.location.reload();
};

