import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import { createClient } from "https://esm.sh/@supabase/supabase-js@2"

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

serve(async (req) => {
  // Handle CORS
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { action, phone, code, name } = await req.json()
    const ARKESEL_API_KEY = Deno.env.get('ARKESEL_API_KEY')
    const SUPABASE_URL = Deno.env.get('SUPABASE_URL')
    const SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')

    if (!ARKESEL_API_KEY) throw new Error('Arkesel API key not configured')

    const supabase = createClient(SUPABASE_URL!, SERVICE_ROLE_KEY!)

    // --- ACTION: SEND OTP ---
    if (action === 'send') {
      const response = await fetch('https://sms.arkesel.com/api/otp/generate', {
        method: 'POST',
        headers: {
          'api-key': ARKESEL_API_KEY,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          expiry: 5,
          length: 6,
          medium: 'sms',
          message: 'Your DigiShe verification code is %otp_code%. It expires in %expiry% minutes.',
          number: phone.replace(/\s+/g, ''), // Clean spaces
          sender_id: 'DigiShe',
          type: 'numeric',
        }),
      })

      const result = await response.json()
      return new Response(JSON.stringify(result), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      })
    }

    // --- ACTION: VERIFY OTP ---
    if (action === 'verify') {
      const response = await fetch('https://sms.arkesel.com/api/otp/verify', {
        method: 'POST',
        headers: {
          'api-key': ARKESEL_API_KEY,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          code: code,
          number: phone.replace(/\s+/g, ''),
        }),
      })

      const result = await response.json()

      // 1100 = Arkesel Success Code
      if (result.code === '1100' || result.code === 1100) {
        // Find or create profile
        let { data: profile, error: fetchError } = await supabase
          .from('profiles')
          .select('*')
          .eq('phone', phone)
          .maybeSingle()

        if (!profile) {
          const { data: newProfile, error: insertError } = await supabase
            .from('profiles')
            .insert({ 
              phone, 
              name: name || 'User', 
              has_completed_onboarding: false 
            })
            .select()
            .single()

          if (insertError) throw insertError
          profile = newProfile
        }

        return new Response(JSON.stringify({ success: true, profile }), {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
          status: 200,
        })
      }

      return new Response(JSON.stringify({ success: false, ...result }), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 400,
      })
    }

    throw new Error('Invalid action')
  } catch (error) {
    return new Response(JSON.stringify({ error: error.message }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 400,
    })
  }
})

