// --- Auth Page ---
const AuthPage: React.FC<{ 
  onAuthComplete: (userData: any) => void;
  onMissingTables: () => void;
}> = ({ onAuthComplete, onMissingTables }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [step, setStep] = useState<'input' | 'otp'>('input');
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [otp, setOtp] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleContinue = async () => {
    if (mode === 'register' && !name) {
      setError('Please enter your full name');
      return;
    }
    if (!phone) {
      setError('Please enter your phone number');
      return;
    }

    setIsLoading(true);
    setError('');

    try {
      // Step 1: Table existence check
      const { data: tableCheck, error: tableError } = await supabase
        .from('profiles')
        .select('id')
        .limit(1);

      if (tableError && (tableError.message.includes('relation "profiles" does not exist') || tableError.code === '42P01')) {
        onMissingTables();
        setIsLoading(false);
        return;
      }

      // Step 2: Account existence check
      const { data: existingProfile } = await supabase
        .from('profiles')
        .select('id')
        .eq('phone', phone)
        .maybeSingle();

      if (mode === 'login' && !existingProfile) {
        setError('No account found for this phone number. Please register first.');
        setIsLoading(false);
        return;
      }

      if (mode === 'register' && existingProfile) {
        setError('This phone number is already registered. Please sign in instead.');
        setIsLoading(false);
        return;
      }

      // Step 3: Trigger SMS via Edge Function
      console.log('Invoking otp-handler...');
      const { data: response, error: funcError } = await supabase.functions.invoke('otp-handler', {
        body: { action: 'send', phone: phone }
      });

      if (funcError) {
        console.error('Edge Function Error:', funcError);
        // Better error extraction
        let errorMsg = 'Could not complete request.';
        try {
          // If status is not 2xx, Supabase client error object might contain the body in some environments
          const body = await (funcError as any).context?.json();
          errorMsg = body?.error || funcError.message;
        } catch (e) {
          errorMsg = funcError.message;
        }

        if (errorMsg.includes('ARKESEL_API_KEY')) {
          setError('Server Configuration Error: ARKESEL_API_KEY is missing from Supabase Secrets. Please add it in your dashboard.');
        } else if (errorMsg.includes('Failed to send a request')) {
          setError('Connectivity Error: Could not reach the authentication server. Ensure the "otp-handler" function is deployed.');
        } else {
          setError(errorMsg);
        }
        setIsLoading(false);
        return;
      }

      if (response?.code === '1000' || response?.code === 1000) {
        setStep('otp');
      } else if (response?.error) {
        setError(response.error);
      } else {
        setError(mapArkeselError(response?.code || 'unknown'));
      }
    } catch (err: any) {
      console.error('Auth Exception:', err);
      setError(err.message || 'An unexpected connection error occurred.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifyOtp = async () => {
    setIsLoading(true);
    setError('');
    try {
      const { data: response, error: funcError } = await supabase.functions.invoke('otp-handler', {
        body: { 
          action: 'verify', 
          phone: phone, 
          code: otp, 
          name: name
        }
      });

      if (funcError) {
        setError(`Verification Error: ${funcError.message}`);
        setIsLoading(false);
        return;
      }

      if (response?.success) {
        onAuthComplete(response.profile);
      } else {
        setError(mapArkeselError(response?.code || '1104'));
      }
    } catch (err: any) {
      setError(err.message || 'Verification failed');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-purple-600 flex flex-col items-center justify-center p-6 text-white">
      <div className="w-full max-w-md space-y-8 text-center">
        <div className="flex flex-col items-center gap-4">
          <div className="bg-white p-4 rounded-3xl shadow-xl">
            <Store className="text-purple-600 w-12 h-12" />
          </div>
          <h1 className="text-4xl font-black">DigiShe</h1>
          <p className="text-purple-100 text-lg font-medium">Digital bookkeeping for women entrepreneurs</p>
        </div>

        <Card className="p-8 space-y-6 text-slate-900">
          {step === 'input' ? (
            <div className="space-y-6">
              <h2 className="text-2xl font-bold text-slate-800">{mode === 'login' ? 'Welcome Back' : 'Create Account'}</h2>

              <div className="space-y-4">
                {mode === 'register' && (
                  <Input 
                    label="Full Name" 
                    placeholder="Enter your name" 
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    disabled={isLoading}
                  />
                )}
                <Input 
                  label="Phone Number" 
                  type="tel"
                  placeholder="e.g. 233544919953" 
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  disabled={isLoading}
                />
              </div>

              {error && (
                <div className="flex items-start gap-2 bg-rose-50 text-rose-600 p-3 rounded-xl text-xs font-medium text-left leading-relaxed border border-rose-100 animate-in fade-in slide-in-from-top-1">
                  <AlertCircle size={16} className="shrink-0 mt-0.5" />
                  <div className="flex flex-col gap-0.5">
                    <span className="font-bold">Error Occurred</span>
                    <span>{error}</span>
                  </div>
                </div>
              )}

              <Button 
                size="xl" 
                className="w-full" 
                onClick={handleContinue}
                disabled={isLoading}
              >
                {isLoading ? <Loader2 className="animate-spin" size={24} /> : <>Continue <ArrowRight size={20} /></>}
              </Button>

              <button 
                onClick={() => {
                  setMode(mode === 'login' ? 'register' : 'login');
                  setError('');
                }}
                disabled={isLoading}
                className="text-purple-600 font-bold hover:underline disabled:opacity-50 pt-2"
              >
                {mode === 'login' ? "Don't have an account? Register" : "Already have an account? Sign in"}
              </button>
            </div>
          ) : (
            <div className="space-y-6 animate-in slide-in-from-right duration-300">
              <div className="flex justify-center">
                <div className="bg-purple-50 p-3 rounded-full text-purple-600">
                  <ShieldCheck size={40} />
                </div>
              </div>

              <div className="space-y-2">
                <h2 className="text-2xl font-bold text-slate-800 text-center">Enter Code</h2>
                <p className="text-slate-500 text-sm text-center">
                  We've sent a 6-digit code to <span className="font-bold text-slate-700">{phone}</span>
                </p>
              </div>

              <div className="flex justify-center gap-2">
                <input 
                  type="text" 
                  maxLength={6}
                  className="w-full max-w-[220px] text-center text-3xl font-black tracking-[0.2em] py-4 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/20"
                  value={otp}
                  placeholder="000000"
                  onChange={(e) => setOtp(e.target.value)}
                  disabled={isLoading}
                  autoFocus
                />
              </div>

              {error && <p className="text-rose-500 text-sm font-medium text-center">{error}</p>}

              <Button 
                size="xl" 
                className="w-full" 
                onClick={handleVerifyOtp}
                disabled={otp.length < 6 || isLoading}
              >
                {isLoading ? <Loader2 className="animate-spin" size={24} /> : 'Verify & Login'}
              </Button>

              <button 
                onClick={() => setStep('input')}
                disabled={isLoading}
                className="text-slate-400 font-medium hover:text-slate-600 flex items-center justify-center gap-1 w-full"
              >
                <ChevronLeft size={16} /> Edit Phone Number
              </button>
            </div>
          )}
        </Card>

        {/* Diagnostic Helper Link */}
        <p className="text-[10px] text-purple-200 opacity-50 font-mono">
          Supabase Project ID: hxpkierzfyotsdtldmej
        </p>
      </div>
    </div>
  );
};

