const AuthPage: React.FC<{ 
  onAuthComplete: (userData: any) => void;
  onMissingTables: () => void;
}> = ({ onAuthComplete, onMissingTables }) => {
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [step, setStep] = useState<'input' | 'otp'>('input');
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [otp, setOtp] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleContinue = async () => {
    if (mode === 'register' && !name) {
      setError('Please enter your full name');
      return;
    }

    // Basic validation to help the user before we call the server
    const digitsOnly = phone.replace(/\D/g, '');
    if (digitsOnly.length < 9) {
      setError('Phone number is too short.');
      return;
    }

    setIsLoading(true);
    setError('');

    try {
      // Step 1: Trigger SMS via Edge Function
      console.log('Sending OTP to:', phone);
      const { data: response, error: funcError } = await supabase.functions.invoke('otp-handler', {
        body: { action: 'send', phone: phone }
      });

      if (funcError) {
        // Detailed error extraction from Supabase client
        let errorMessage = 'Server failed to respond.';
        if (funcError instanceof Error) {
          try {
            // Some environments return JSON in the message
            const details = JSON.parse(funcError.message);
            errorMessage = details.error || funcError.message;
          } catch (e) {
            errorMessage = funcError.message;
          }
        }

        // Check for table existence error
        if (errorMessage.toLowerCase().includes('profiles') && errorMessage.toLowerCase().includes('not found')) {
          onMissingTables();
          setIsLoading(false);
          return;
        }

        setError(errorMessage);
        setIsLoading(false);
        return;
      }

      if (response?.code === '1000' || response?.code === 1000) {
        setStep('otp');
      } else {
        setError(mapArkeselError(response?.code || 'unknown'));
      }
    } catch (err: any) {
      setError(err.message || 'Connection lost.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifyOtp = async () => {
    setIsLoading(true);
    setError('');
