// --- Main App ---
export default function App() {
  const [state, setState] = useState<AppState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : initialState;
    } catch (e) {
      return initialState;
    }
  });
  const [insight, setInsight] = useState("Keep up the great work!");
  const [isSyncing, setIsSyncing] = useState(false);
  const [showSetup, setShowSetup] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

  useEffect(() => {
    if (state.user) localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  useEffect(() => {
    if (state.business && state.transactions.length > 0) {
      getBusinessInsight(state.business, state.transactions).then(setInsight);
    }
  }, [state.business, state.transactions]);

  useEffect(() => {
    if (state.user?.phoneNumber) fetchDataFromSupabase(state.user.phoneNumber);
  }, [state.user?.phoneNumber]);

  const fetchDataFromSupabase = async (phone: string) => {
    setIsSyncing(true);
    try {
      const { data: profile } = await supabase.from('profiles').select('*').eq('phone', phone).maybeSingle();
      if (profile) {
        const { data: business } = await supabase.from('businesses').select('*').eq('user_id', profile.id).maybeSingle();
        let transactions: any[] = [];
        if (business) {
          const { data: txs } = await supabase.from('transactions').select('*').eq('business_id', business.id);
          transactions = txs || [];
        }
        setState(prev => ({
          ...prev,
          user: { phoneNumber: phone, name: profile.name, hasCompletedOnboarding: profile.has_completed_onboarding },
          business: business ? { name: business.name, type: business.type, startDate: business.start_date } : null,
          transactions: transactions.map(t => ({ id: t.id, userId: phone, type: t.type, amount: t.amount, category: t.category, date: t.date }))
        }));
      }
    } catch (err) { console.error("Sync error:", err); } 
    finally { setIsSyncing(false); }
  };

  const performLogout = () => {
    localStorage.removeItem(STORAGE_KEY);
    setState({ ...initialState });
    setInsight("Keep up the great work!");
    setShowLogoutConfirm(false);
  };

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={!state.user ? <AuthPage onAuthComplete={(p) => setState(prev => ({...prev, user: { phoneNumber: p.phone, name: p.name, hasCompletedOnboarding: p.has_completed_onboarding }}))} onMissingTables={() => setShowSetup(true)} /> : (state.user.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <Navigate to="/onboarding" replace />)} />
        <Route path="/dashboard" element={state.user?.hasCompletedOnboarding ? <Dashboard state={state} onLogout={() => setShowLogoutConfirm(true)} insight={insight} /> : <Navigate to="/login" replace />} />
        <Route path="/record/:type" element={state.user?.hasCompletedOnboarding ? <RecordPage type="sale" onSave={(amt, cat) => {}} recentTransactions={[]} /> : <Navigate to="/login" replace />} />
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
      {showSetup && <DatabaseSetupModal onClose={() => setShowSetup(false)} />}
      {showLogoutConfirm && <LogoutConfirmModal onConfirm={performLogout} onCancel={() => setShowLogoutConfirm(false)} />}
    </HashRouter>
  );
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import { createClient } from "https://esm.sh/@supabase/supabase-js@2"

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })

  try {
    const { action, phone, code, name } = await req.json()
    const env = (Deno as any).env
    const ARKESEL_KEY = env.get('ARKESEL_API_KEY')
    const SUPABASE_URL = env.get('SUPABASE_URL')
    const SERVICE_KEY = env.get('SUPABASE_SERVICE_ROLE_KEY')

    if (!ARKESEL_KEY) throw new Error('ARKESEL_API_KEY is missing in Supabase Secrets.')

    const supabase = createClient(SUPABASE_URL, SERVICE_KEY)

    // Robust Phone Cleaning for West Africa (Ghana focus)
    // If it starts with 0, it's likely a local number missing the country code (233)
    let cleanPhone = phone.replace(/\D/g, '')
    if (cleanPhone.startsWith('0')) {
      cleanPhone = '233' + cleanPhone.substring(1)
    }

    if (action === 'send') {
      const response = await fetch('https://sms.arkesel.com/api/otp/generate', {
        method: 'POST',
        headers: { 'api-key': ARKESEL_KEY, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          expiry: 5, length: 6, medium: 'sms', sender_id: 'DigiShe',
          message: 'Your DigiShe code is %otp_code%. It expires in %expiry% min.',
          number: cleanPhone, type: 'numeric'
        }),
      })
      return new Response(JSON.stringify(await response.json()), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }

    if (action === 'verify') {
      const response = await fetch('https://sms.arkesel.com/api/otp/verify', {
        method: 'POST',
        headers: { 'api-key': ARKESEL_KEY, 'Content-Type': 'application/json' },
        body: JSON.stringify({ code, number: cleanPhone }),
      })
      const result = await response.json()

      if (result.code === '1100' || result.code === 1100) {
        let { data: profile } = await supabase.from('profiles').select('*').eq('phone', phone).maybeSingle()
        if (!profile) {
          const { data: newP, error: iErr } = await supabase.from('profiles').insert({ phone, name: name || 'User' }).select().single()
          if (iErr) throw iErr
          profile = newP
        }
        return new Response(JSON.stringify({ success: true, profile }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
      }
      return new Response(JSON.stringify({ success: false, ...result }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }
  } catch (error) {
    return new Response(JSON.stringify({ error: error.message }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 })
  }
})

