);

CREATE TABLE IF NOT EXISTS public.businesses (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
  name text NOT NULL,
  type text NOT NULL,
  location text,
  is_active boolean DEFAULT false,
  start_date timestamp with time zone NOT NULL,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.transactions (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  business_id uuid REFERENCES public.businesses(id) ON DELETE CASCADE,
  type text CHECK (type IN ('sale', 'expense')),
  amount numeric NOT NULL,
  category text,
  date date NOT NULL,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.savings (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  business_id uuid REFERENCES public.businesses(id) ON DELETE CASCADE,
  amount numeric NOT NULL,
  destination text CHECK (destination IN ('Bank', 'Mobile Money')),
  date date NOT NULL,
  created_at timestamp with time zone DEFAULT now()
);`;

// --- Helper Functions (No Changes) ---
const formatDate = (date: Date) => date.toISOString().split('T')[0];
const normalizePhone = (phone: string): string => {
  let cleaned = phone.replace(/\D/g, '');
  if (cleaned.startsWith('0') && cleaned.length === 10) cleaned = '233' + cleaned.substring(1);
  else if (cleaned.length === 9) cleaned = '233' + cleaned;
  return cleaned;
};
const getWeeklyData = (transactions: Transaction[]) => {
  const last7Days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(); d.setDate(d.getDate() - i); return formatDate(d);
  }).reverse();
  return last7Days.map(date => {
    const daily = transactions.filter(t => t.date === date);
    return {
      date: new Date(date).toLocaleDateString('en-US', { weekday: 'short' }),
      fullDate: date,
      sales: daily.filter(t => t.type === 'sale').reduce((acc, t) => acc + t.amount, 0),
      expenses: daily.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0)
    };
  });
};
const mapArkeselError = (code: string | number) => {
  const errors: Record<string, string> = { '1005': 'Invalid phone format.', '1007': 'SMS service unavailable.', '1104': 'Incorrect verification code.', '1105': 'Code expired.' };
  return errors[String(code)] || `Error: ${code}`;
};

