const AdminDashboard: React.FC<{ user: User; onLogout: () => void }> = ({ user, onLogout }) => {
  const [businesses, setBusinesses] = useState<any[]>([]); const [isLoading, setIsLoading] = useState(true); const navigate = useNavigate();
  const fetchAllBusinesses = async () => { setIsLoading(true); try { const { data, error } = await supabase.from('businesses').select('*, profiles:user_id (phone, name)').order('created_at', { ascending: false }); if (error) throw error; setBusinesses(data || []); } catch (err) { console.error("Admin fetch error:", err); } finally { setIsLoading(false); } };
  useEffect(() => { if (!user.isAdmin) { navigate('/dashboard'); return; } fetchAllBusinesses(); }, [user]);
  const toggleActivation = async (businessId: string, currentStatus: boolean) => { try { const { error } = await supabase.from('businesses').update({ is_active: !currentStatus }).eq('id', businessId); if (error) throw error; setBusinesses(prev => prev.map(b => b.id === businessId ? { ...b, is_active: !currentStatus } : b)); } catch (err) { alert("Failed to update status"); } };
  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
