  const handleSubmit = async () => { setIsSaving(true); setError(''); try { await onComplete({ name, type, location, startDate: new Date().toISOString(), isActive: false }); } catch (err: any) { setError(err.message || 'Failed to save'); } finally { setIsSaving(false); } };
