};

// --- Main App ---
export default function App() {
  const [state, setState] = useState<AppState>(() => { try { const saved = localStorage.getItem(STORAGE_KEY); return saved ? JSON.parse(saved) : initialState; } catch (e) { return initialState; } });
  const [insight, setInsight] = useState("Keep up the great work!");
  const [showSetup, setShowSetup] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [showCatCreator, setShowCatCreator] = useState(false);
  const [isSyncing, setIsSyncing] = useState(true);
  useEffect(() => { if (state.user) localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }, [state]);
  useEffect(() => { if (state.business?.isActive && state.transactions.length > 0) getBusinessInsight(state.business, state.transactions).then(setInsight); }, [state.business, state.transactions]);
  useEffect(() => { if (state.user?.phoneNumber) { fetchDataFromSupabase(state.user.phoneNumber).finally(() => { setTimeout(() => setIsSyncing(false), 800); }); } else { setIsSyncing(false); } }, [state.user?.phoneNumber]);
  const fetchDataFromSupabase = async (phone: string) => { const normalized = normalizePhone(phone); try { const { data: profile } = await supabase.from('profiles').select('*').eq('phone', normalized).maybeSingle(); if (profile) { const { data: business } = await supabase.from('businesses').select('*').eq('user_id', profile.id).maybeSingle(); let transactions = []; let savings = []; if (business) { const { data: txs } = await supabase.from('transactions').select('*').eq('business_id', business.id); const { data: svs } = await supabase.from('savings').select('*').eq('business_id', business.id); transactions = txs || []; savings = svs || []; } setState(prev => ({ ...prev, user: { phoneNumber: normalized, name: profile.name, isAdmin: profile.is_admin, hasCompletedOnboarding: profile.has_completed_onboarding }, business: business ? { id: business.id, name: business.name, type: business.type as BusinessType, location: business.location, isActive: business.is_active, startDate: business.start_date } : null, transactions: transactions.map(t => ({ id: t.id, userId: normalized, type: t.type, amount: parseFloat(t.amount), category: t.category, date: t.date })), savings: savings.map(s => ({ id: s.id, businessId: business.id, amount: parseFloat(s.amount), destination: s.destination, date: s.date })), entryCount: transactions.length })); } } catch (err) { console.error("Supabase error:", err); } };
  const handleOnboarding = async (business: Business) => { if (!state.user) return; const normalized = normalizePhone(state.user.phoneNumber); const { data: profile } = await supabase.from('profiles').select('id').eq('phone', normalized).single(); if (profile) { const { data: newBiz, error: bizError } = await supabase.from('businesses').insert({ user_id: profile.id, name: business.name, type: business.type, location: business.location, is_active: false, start_date: business.startDate }).select().single(); if (bizError) throw bizError; await supabase.from('profiles').update({ has_completed_onboarding: true }).eq('id', profile.id); setState(prev => ({ ...prev, business: { ...business, id: newBiz.id, isActive: false }, user: prev.user ? { ...prev.user, hasCompletedOnboarding: true } : null })); } };
  const addTransaction = async (type: 'sale' | 'expense', amount: number, category: string) => { if (!state.user || !state.business) return; const normalized = normalizePhone(state.user.phoneNumber); const dateStr = formatDate(new Date()); const newCount = state.entryCount + 1; const newTx: Transaction = { id: Math.random().toString(36).substr(2, 9), userId: normalized, type, amount, category, date: dateStr }; setState(prev => ({ ...prev, transactions: [...prev.transactions, newTx], entryCount: newCount, showCategoryPrompt: newCount === 3 })); await supabase.from('transactions').insert({ business_id: state.business.id, type, amount, category, date: dateStr }); };
  const addSaving = async (amount: number, destination: 'Bank' | 'Mobile Money') => { if (!state.user || !state.business?.id) return; const dateStr = formatDate(new Date()); const newS: Saving = { id: Math.random().toString(36).substr(2, 9), businessId: state.business.id, amount, destination, date: dateStr }; setState(prev => ({ ...prev, savings: [...prev.savings, newS] })); await supabase.from('savings').insert({ business_id: state.business.id, amount, destination, date: dateStr }); };
  const handleAddCategory = (name: string) => { setState(prev => ({ ...prev, customCategories: [...prev.customCategories, name], showCategoryPrompt: false })); setShowCatCreator(false); };
  const performLogout = () => { localStorage.removeItem(STORAGE_KEY); setState({ ...initialState }); setInsight("Keep up the great work!"); setShowLogoutConfirm(false); };
  const user = state.user; const business = state.business; if (isSyncing) return <SplashScreen />;
  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={<LandingPage user={user} />} />
        <Route path="/login" element={!user ? <AuthPage onAuthComplete={(p) => setState(prev => ({...prev, user: { phoneNumber: p.phone, name: p.name, isAdmin: p.is_admin, hasCompletedOnboarding: p.has_completed_onboarding }}))} onMissingTables={() => setShowSetup(true)} /> : (user.hasCompletedOnboarding ? (business?.isActive ? <Navigate to="/dashboard" replace /> : <Navigate to="/pending" replace />) : <Navigate to="/onboarding" replace />)} />
        <Route path="/onboarding" element={user ? (user.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <OnboardingPage onComplete={handleOnboarding} />) : <Navigate to="/login" replace />} />
        <Route path="/pending" element={user?.hasCompletedOnboarding ? (business?.isActive ? <Navigate to="/dashboard" replace /> : <PendingActivationPage onLogout={() => setShowLogoutConfirm(true)} />) : <Navigate to="/login" replace />} />
        <Route path="/admin" element={user?.isAdmin ? <AdminDashboard user={user} onLogout={() => setShowLogoutConfirm(true)} /> : <Navigate to="/dashboard" replace />} />
        <Route path="/dashboard" element={user?.hasCompletedOnboarding ? (business?.isActive ? <Dashboard state={state} onLogout={() => setShowLogoutConfirm(true)} insight={insight} onShowCategoryPrompt={() => { if(state.entryCount >= 3) setShowCatCreator(true); }} /> : <Navigate to="/pending" replace />) : <Navigate to="/login" replace />} />
        <Route path="/savings" element={user?.hasCompletedOnboarding ? (business?.isActive ? <SavingsHub state={state} /> : <Navigate to="/pending" replace />) : <Navigate to="/login" replace />} />
        <Route path="/record-saving" element={user?.hasCompletedOnboarding ? (business?.isActive ? <RecordSavingPage onSave={addSaving} /> : <Navigate to="/pending" replace />) : <Navigate to="/login" replace />} />
        <Route path="/record/:type" element={<RecordRouteHandler user={user} business={business} customCategories={state.customCategories} transactions={state.transactions} onSave={addTransaction} />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
      {showSetup && <DatabaseSetupModal onClose={() => setShowSetup(false)} />}
      {showLogoutConfirm && <LogoutConfirmModal onConfirm={performLogout} onCancel={() => setShowLogoutConfirm(false)} />}
      {showCatCreator && <CreateCategoryModal onAdd={handleAddCategory} onCancel={() => { setShowCatCreator(false); setState(prev => ({ ...prev, showCategoryPrompt: false })); }} />}
    </HashRouter>
  );
}

