const Login = ({ onAuth }: { onAuth: (user: User) => void }) => {
  const [phone, setPhone] = useState('');
  const [step, setStep] = useState<'phone' | 'otp'>('phone');
  const [otp, setOtp] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSendOTP = async () => {
    setLoading(true);
    // Mock OTP sending
    setTimeout(() => {
      setStep('otp');
      setLoading(false);
    }, 1000);
  };

  const handleVerify = () => {
    setLoading(true);
    // Mock Verification
    setTimeout(() => {
      const mockUser: User = {
        phoneNumber: phone,
        name: 'Entrepreneur',
        hasCompletedOnboarding: false,
        isAdmin: false
      };
      onAuth(mockUser);
      navigate('/onboarding');
      setLoading(false);
    }, 1000);
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4 py-12 bg-slate-50">
      <Card className="w-full max-w-md shadow-2xl shadow-purple-200/50">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-purple-600 rounded-2xl flex items-center justify-center text-white mx-auto mb-4 shadow-lg shadow-purple-500/20">
            <Store size={32} />
          </div>
          <h2 className="text-2xl font-bold text-slate-900">Welcome to DigiShe</h2>
          <p className="text-slate-500 mt-2">Let's get your business digital.</p>
        </div>

        {step === 'phone' ? (
          <div className="flex flex-col gap-6">
            <Input 
              label="Phone Number" 
              placeholder="e.g. 233 24 000 0000" 
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
            />
            <Button onClick={handleSendOTP} disabled={!phone || loading} className="w-full">
              {loading ? <Loader2 className="animate-spin" size={20} /> : "Continue"}
            </Button>
          </div>
        ) : (
          <div className="flex flex-col gap-6">
            <div className="text-center">
              <p className="text-sm text-slate-600 mb-4">Enter the 6-digit code sent to {phone}</p>
              <Input 
                placeholder="0 0 0 0 0 0" 
                className="text-center text-2xl tracking-[0.5em] font-bold"
                maxLength={6}
                value={otp}
                onChange={(e) => setOtp(e.target.value)}
              />
            </div>
            <Button onClick={handleVerify} disabled={otp.length !== 6 || loading} className="w-full">
              {loading ? <Loader2 className="animate-spin" size={20} /> : "Verify Code"}
            </Button>
            <button className="text-sm text-purple-600 font-medium hover:underline" onClick={() => setStep('phone')}>
              Change Phone Number
            </button>
          </div>
        )}
      </Card>
    </div>
  );
};

