              onChange={(e) => setData({...data, name: e.target.value})}
            />
            <Button className="w-full mt-8" onClick={() => setStep(2)} disabled={!data.name}>Next</Button>
          </div>
        )}

        {step === 2 && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h2 className="text-2xl font-bold text-slate-900 mb-2">What kind of business?</h2>
