                <button
                  key={type}
                  className={`p-4 rounded-xl border-2 transition-all text-left ${data.type === type ? 'border-purple-600 bg-purple-50 text-purple-700' : 'border-slate-100 hover:border-slate-200 text-slate-600'}`}
