            <div className="bg-purple-50 p-6 rounded-2xl border border-purple-100 mb-8">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-purple-600 shadow-sm">
                  <CheckCircle2 size={24} />
                </div>
                <div>
                  <p className="font-bold text-slate-900">{data.name}</p>
                  <p className="text-sm text-slate-500">{data.type} • Started {data.startDate}</p>
