    setTimeout(() => {
      setLoading(false);
    }, 1000);
  }, []);

  useEffect(() => {
    if (business) {
      getBusinessInsight(business, transactions).then(setInsight);
    }
  }, [business, transactions]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-slate-50">
