        <h2 className="font-bold text-slate-700">Manage Businesses</h2>
        {loading ? <Loader2 className="animate-spin mx-auto" /> : businesses.map(biz => (
          <Card key={biz.id} className="flex justify-between items-center">
            <div>
              <p className="font-bold text-lg">{biz.name}</p>
              <p className="text-sm text-slate-500">{biz.profiles?.name} • {biz.profiles?.phone}</p>
            </div>
            <Button variant={biz.is_active ? 'outline' : 'primary'} onClick={() => toggleStatus(biz.id, biz.is_active)}>
              {biz.is_active ? 'Deactivate' : 'Activate'}
            </Button>
          </Card>
        ))}
      </main>
    </div>
  );
};
