// Use named import for Dexie to ensure proper type resolution in all environments
import { Dexie, type Table } from 'dexie';
import { Transaction, Saving, Business } from '../types';

export type LocalTransaction = Transaction & { synced: number };
export type LocalSaving = Saving & { synced: number };
export type LocalBusiness = Business & { synced: number; userId: string };

/**
 * DigiShe local database for offline-first support.
 * Using Dexie for IndexedDB management.
 */
export class DigiSheDB extends Dexie {
  transactions!: Table<LocalTransaction>;
  savings!: Table<LocalSaving>;
  businesses!: Table<LocalBusiness>;

  constructor() {
    super('DigiSheDB');
    // Initialize database schema and versioning.
    // Line below was causing error due to type mismatch in some Dexie versions.
    this.version(1).stores({
      transactions: 'id, userId, type, synced, date',
      savings: 'id, businessId, synced, date',
      businesses: 'id, userId, synced'
    });
  }
}

export const db = new DigiSheDB();

