const OfflineWarning: React.FC<{ lastSyncTime: number | null; pendingCount: number }> = ({ lastSyncTime, pendingCount }) => {
  const isStale = lastSyncTime ? (Date.now() - lastSyncTime > 1000 * 60 * 60 * 24 * 2) : false; // 2 days
  const isUrgent = pendingCount > 50 || isStale;

  if (pendingCount === 0) return null;

  return (
    <div className={`p-3 rounded-xl flex items-center gap-3 animate-in slide-in-from-top-2 ${isUrgent ? 'bg-rose-50 border border-rose-100 text-rose-700' : 'bg-amber-50 border border-amber-100 text-amber-700'}`}>
      <AlertCircle size={18} className="shrink-0" />
      <div className="flex-1">
        <p className="text-xs font-bold">
          {isUrgent ? 'Critical: Sync required' : 'Record saved locally'}
        </p>
        <p className="text-[10px] opacity-80">
          {pendingCount} entries are only on this phone. {isUrgent ? 'Please connect to internet to avoid data loss.' : 'They will sync when you get back online.'}
