// --- Auth Page ---
const AuthPage: React.FC<{ onAuthComplete: (profile: any) => void; onMissingTables: () => void }> = ({ onAuthComplete, onMissingTables }) => {
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [code, setCode] = useState('');
  const [step, setStep] = useState<'info' | 'otp'>('info');
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSendOTP = async () => {
    setLoading(true); setError('');
    try {
      const { data, error: err } = await supabase.functions.invoke('otp-handler', {
        body: { action: 'send', phone, name, mode }
      });
      if (err || (data && !data.success)) {
        if (data?.code === 'PGRST116') onMissingTables();
        setError(err?.message || data?.error || 'Failed to send code.');
      } else { setStep('otp'); }
    } catch (e: any) { setError(e.message); }
    finally { setLoading(false); }
  };

  const handleVerifyOTP = async () => {
    setLoading(true); setError('');
    try {
      const { data, error: err } = await supabase.functions.invoke('otp-handler', {
        body: { action: 'verify', phone, code }
      });
      if (err || (data && !data.success)) setError('Invalid code.');
      else onAuthComplete(data.profile);
    } catch (e: any) { setError(e.message); }
    finally { setLoading(false); }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
      <Card className="max-w-md w-full p-8 space-y-6">
        <div className="text-center">
          <img src={LOGO_URL} alt="DigiShe" className="h-10 mx-auto mb-4" />
          <h2 className="text-2xl font-bold">{mode === 'login' ? 'Login' : 'Join DigiShe'}</h2>
        </div>
        {error && <div className="p-3 bg-rose-50 text-rose-500 rounded-lg text-sm">{error}</div>}
        {step === 'info' ? (
          <div className="space-y-4">
             {mode === 'register' && <Input label="Full Name" value={name} onChange={e => setName(e.target.value)} />}
             <Input label="Phone Number" value={phone} onChange={e => setPhone(e.target.value)} />
             <Button className="w-full" onClick={handleSendOTP} disabled={loading}>{loading ? <Loader2 className="animate-spin" /> : 'Get Code'}</Button>
             <button className="w-full text-purple-600 text-sm font-bold" onClick={() => setMode(mode === 'login' ? 'register' : 'login')}>
               {mode === 'login' ? 'Need an account?' : 'Already have an account?'}
             </button>
          </div>
        ) : (
          <div className="space-y-4">
             <Input label="Verification Code" value={code} onChange={e => setCode(e.target.value)} />
             <Button className="w-full" onClick={handleVerifyOTP} disabled={loading}>{loading ? <Loader2 className="animate-spin" /> : 'Enter App'}</Button>
             <button className="w-full text-slate-400 text-sm" onClick={() => setStep('info')}>Change number</button>
          </div>
        )}
      </Card>
    </div>
  );
};

