      onSave(type, v, cat); setDone(true);
      setTimeout(() => navigate('/dashboard'), 1000);
    }
  };
  if (done) return <div className="min-h-screen bg-emerald-500 flex items-center justify-center text-white font-black text-3xl">Saved!</div>;
