              <button key={c} onClick={() => setCat(c)} className={`p-4 rounded-xl text-xs font-bold border-2 ${cat === c ? 'bg-purple-50 border-purple-500 text-purple-600' : 'border-slate-100 text-slate-500'}`}>{c}</button>
