               onClick={() => setDestination('Bank')}
               className={`flex-1 py-4 rounded-xl font-bold ${destination === 'Bank' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500'}`}
             >Bank</button>
             <button 
               onClick={() => setDestination('Mobile Money')}
               className={`flex-1 py-4 rounded-xl font-bold ${destination === 'Mobile Money' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500'}`}
             >MoMo</button>
