          <Input label="Amount to Save" type="number" value={amount} onChange={(e) => setAmount(e.target.value)} autoFocus />
          <Button size="xl" className="w-full !bg-indigo-600 shadow-lg" onClick={handleSave}>Confirm Saving</Button>
        </Card>
      </main>
    </div>
  );
};

import { Dexie, type Table } from 'dexie';
import { Transaction, Saving } from '../types';

export type LocalTransaction = Transaction & { synced: number };
export type LocalSaving = Saving & { synced: number };

export class DigiSheDB extends Dexie {
  transactions!: Table<LocalTransaction>;
  savings!: Table<LocalSaving>;

  constructor() {
    super('DigiSheDB');
    this.version(1).stores({
      transactions: 'id, userId, type, synced, date',
      savings: 'id, businessId, synced, date'
    });
  }
}

export const db = new DigiSheDB();

