// --- Main App ---
export default function App() {
  const [state, setState] = useState<AppState>(initialState);
  const [insight, setInsight] = useState("Keep up the great work!");
  const [showSetup, setShowSetup] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [showCatCreator, setShowCatCreator] = useState(false);

  const [isInitializing, setIsInitializing] = useState(true);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [pendingSyncCount, setPendingSyncCount] = useState(0);

  // Persistence and Online status
  useEffect(() => {
    if ('storage' in navigator && 'persist' in navigator.storage) {
      navigator.storage.persist();
    }
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Sync state update listener
  const updatePendingCount = useCallback(async () => {
    const txCount = await db.transactions.where('synced').equals(0).count();
    const svCount = await db.savings.where('synced').equals(0).count();
    setPendingSyncCount(txCount + svCount);
  }, []);

  // Background Sync Engine
  const syncData = useCallback(async () => {
    if (!isOnline || isSyncing) return;
    setIsSyncing(true);
    try {
      // Sync Transactions
      const unsyncedTx = await db.transactions.where('synced').equals(0).toArray();
      for (const tx of unsyncedTx) {
        const { error } = await supabase.from('transactions').insert({
          id: tx.id,
          business_id: state.business?.id,
          type: tx.type,
          amount: tx.amount,
          category: tx.category,
          date: tx.date
        });
        if (!error) await db.transactions.update(tx.id, { synced: 1 });
      }

      // Sync Savings
      const unsyncedSv = await db.savings.where('synced').equals(0).toArray();
      for (const sv of unsyncedSv) {
        const { error } = await supabase.from('savings').insert({
          id: sv.id,
          business_id: sv.businessId,
          amount: sv.amount,
          destination: sv.destination,
          date: sv.date
        });
        if (!error) await db.savings.update(sv.id, { synced: 1 });
      }

      await updatePendingCount();
    } catch (err) {
      console.error("Background sync error:", err);
    } finally {
      setIsSyncing(false);
    }
  }, [isOnline, isSyncing, state.business?.id, updatePendingCount]);

  // Initial load from local store
  useEffect(() => {
    const init = async () => {
      const txs = await db.transactions.toArray();
      const svs = await db.savings.toArray();
      const stored = localStorage.getItem(STORAGE_KEY);
      const parsed = stored ? JSON.parse(stored) : initialState;

      setState(prev => ({
        ...parsed,
        transactions: txs,
        savings: svs,
        entryCount: txs.length
      }));

      await updatePendingCount();
      setIsInitializing(false);
    };
    init();
  }, [updatePendingCount]);

  // Sync trigger when online
  useEffect(() => {
    if (isOnline && pendingSyncCount > 0) {
      const timer = setTimeout(() => syncData(), 3000);
      return () => clearTimeout(timer);
    }
  }, [isOnline, pendingSyncCount, syncData]);

  useEffect(() => {
    if (state.user) localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...state, transactions: [], savings: [] }));
  }, [state]);

  useEffect(() => {
    if (state.business?.isActive && state.transactions.length > 0) getBusinessInsight(state.business, state.transactions).then(setInsight);
  }, [state.business, state.transactions]);

  const addTransaction = async (type: 'sale' | 'expense', amount: number, category: string) => {
    if (!state.user || !state.business) return;
    const dateStr = formatDate(new Date());
    const newTx: LocalTransaction = { 
      id: crypto.randomUUID(), 
      userId: state.user.phoneNumber, 
      type, 
      amount, 
      category, 
      date: dateStr,
      synced: 0
    };

    // Offline-First: Always save to local DB first
    await db.transactions.add(newTx);

    setState(prev => {
      const newCount = prev.entryCount + 1;
      return { 
        ...prev, 
        transactions: [...prev.transactions, newTx], 
        entryCount: newCount,
        showCategoryPrompt: newCount === 3
      };
    });

    updatePendingCount();
    if (isOnline) syncData();
  };

  const addSaving = async (amount: number, destination: 'Bank' | 'Mobile Money') => {
    if (!state.user || !state.business || !state.business.id) return;
    const dateStr = formatDate(new Date());
    const newS: LocalSaving = { 
      id: crypto.randomUUID(), 
      businessId: state.business.id, 
      amount, 
      destination, 
      date: dateStr,
      synced: 0
    };

    await db.savings.add(newS);
    setState(prev => ({ ...prev, savings: [...prev.savings, newS] }));

    updatePendingCount();
    if (isOnline) syncData();
  };

  const handleOnboarding = async (business: Business) => {
    if (!state.user) return;
    const normalized = normalizePhone(state.user.phoneNumber);
    const { data: profile } = await supabase.from('profiles').select('id').eq('phone', normalized).single();
    if (profile) {
      const { data: newBiz, error: bizError } = await supabase.from('businesses').insert({ 
        user_id: profile.id, 
        name: business.name, 
        type: business.type, 
        location: business.location, 
        is_active: false, 
        start_date: business.startDate 
      }).select().single();
      if (bizError) throw bizError;
      await supabase.from('profiles').update({ has_completed_onboarding: true }).eq('id', profile.id);
      setState(prev => ({ ...prev, business: { ...business, id: newBiz.id, isActive: false }, user: prev.user ? { ...prev.user, hasCompletedOnboarding: true } : null }));
    }
  };

  const handleAddCategory = (name: string) => {
    setState(prev => ({ ...prev, customCategories: [...prev.customCategories, name], showCategoryPrompt: false }));
    setShowCatCreator(false);
  };

  const performLogout = () => { 
    localStorage.removeItem(STORAGE_KEY); 
    db.transactions.clear();
    db.savings.clear();
    setState({ ...initialState }); 
    setInsight("Keep up the great work!"); 
    setShowLogoutConfirm(false); 
  };

  if (isInitializing) return <SplashScreen />;

  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={<LandingPage user={state.user} />} />
        <Route path="/login" element={!state.user ? <AuthPage onAuthComplete={(p) => setState(prev => ({...prev, user: { phoneNumber: p.phone, name: p.name, isAdmin: p.is_admin, hasCompletedOnboarding: p.has_completed_onboarding }}))} onMissingTables={() => setShowSetup(true)} /> : (state.user.hasCompletedOnboarding ? (state.business?.isActive ? <Navigate to="/dashboard" replace /> : <Navigate to="/pending" replace />) : <Navigate to="/onboarding" replace />)} />
        <Route path="/onboarding" element={state.user ? (state.user.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <OnboardingPage onComplete={handleOnboarding} />) : <Navigate to="/login" replace />} />
        <Route path="/pending" element={state.user?.hasCompletedOnboarding ? (state.business?.isActive ? <Navigate to="/dashboard" replace /> : <PendingActivationPage onLogout={() => setShowLogoutConfirm(true)} />) : <Navigate to="/login" replace />} />
        <Route path="/admin" element={state.user?.isAdmin ? <AdminDashboard user={state.user} onLogout={() => setShowLogoutConfirm(true)} /> : <Navigate to="/dashboard" replace />} />
        <Route path="/dashboard" element={state.user?.hasCompletedOnboarding ? (state.business?.isActive ? <Dashboard state={state} onLogout={() => setShowLogoutConfirm(true)} insight={insight} onShowCategoryPrompt={() => { if(state.entryCount >= 3) setShowCatCreator(true); }} isOnline={isOnline} pendingSyncCount={pendingSyncCount} isSyncing={isSyncing} onSync={syncData} /> : <Navigate to="/pending" replace />) : <Navigate to="/login" replace />} />
        <Route path="/savings" element={state.user?.hasCompletedOnboarding ? (state.business?.isActive ? <SavingsHub state={state} /> : <Navigate to="/pending" replace />) : <Navigate to="/login" replace />} />
        <Route path="/record-saving" element={state.user?.hasCompletedOnboarding ? (state.business?.isActive ? <RecordSavingPage onSave={addSaving} /> : <Navigate to="/pending" replace />) : <Navigate to="/login" replace />} />
        <Route path="/record/:type" element={<RecordRouteHandler user={state.user} business={state.business} customCategories={state.customCategories} transactions={state.transactions} onSave={addTransaction} />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
      {showSetup && <DatabaseSetupModal onClose={() => setShowSetup(false)} />}
      {showLogoutConfirm && <LogoutConfirmModal onConfirm={performLogout} onCancel={() => setShowLogoutConfirm(false)} />}
      {showCatCreator && <CreateCategoryModal onAdd={handleAddCategory} onCancel={() => { setShowCatCreator(false); setState(prev => ({ ...prev, showCategoryPrompt: false })); }} />}
    </HashRouter>
  );
}

import { Dexie, type Table } from 'dexie';
import { Transaction, Saving } from '../types';

export type LocalTransaction = Transaction & { 
  synced: number; 
  client_updated_at: number;
};
export type LocalSaving = Saving & { 
  synced: number; 
  client_updated_at: number;
};

export class DigiSheDB extends Dexie {
  transactions!: Table<LocalTransaction>;
  savings!: Table<LocalSaving>;

  constructor() {
    super('DigiSheDB');
    this.version(1).stores({
      transactions: 'id, userId, type, synced, date, client_updated_at',
      savings: 'id, businessId, synced, date, client_updated_at'
    });
  }
}

export const db = new DigiSheDB();

