// --- Main App ---
export default function App() {
  const [state, setState] = useState<AppState>(initialState);
  const [insight, setInsight] = useState("Keep up the great work!");
  const [showSetup, setShowSetup] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [isInitializing, setIsInitializing] = useState(true);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [pendingSyncCount, setPendingSyncCount] = useState(0);

  useEffect(() => {
    if ('storage' in navigator && 'persist' in navigator.storage) navigator.storage.persist();
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const updateCount = useCallback(async () => {
    const tCount = await db.transactions.where('synced').equals(0).count();
    const sCount = await db.savings.where('synced').equals(0).count();
    setPendingSyncCount(tCount + sCount);
  }, []);

  const syncData = useCallback(async () => {
    if (!isOnline || isSyncing) return;
    setIsSyncing(true);
    try {
      const uTx = await db.transactions.where('synced').equals(0).toArray();
      for (const t of uTx) {
        const { error } = await supabase.from('transactions').insert({
          id: t.id, business_id: state.business?.id, type: t.type, amount: t.amount, category: t.category, date: t.date
        });
        if (!error) await db.transactions.update(t.id, { synced: 1 });
      }
      const uSv = await db.savings.where('synced').equals(0).toArray();
      for (const s of uSv) {
        const { error } = await supabase.from('savings').insert({
          id: s.id, business_id: s.businessId, amount: s.amount, destination: s.destination, date: s.date
        });
        if (!error) await db.savings.update(s.id, { synced: 1 });
      }
      await updateCount();
    } catch (err) {
      console.error(err);
    } finally {
      setIsSyncing(false);
    }
  }, [isOnline, isSyncing, state.business?.id, updateCount]);

  useEffect(() => {
    const init = async () => {
      const txs = await db.transactions.toArray();
      const svs = await db.savings.toArray();
      const stored = localStorage.getItem(STORAGE_KEY);
      const parsed = stored ? JSON.parse(stored) : initialState;
      setState(prev => ({ ...parsed, transactions: txs, savings: svs, entryCount: txs.length }));
      await updateCount();
      setIsInitializing(false);
    };
    init();
  }, [updateCount]);

  useEffect(() => {
    if (isOnline && pendingSyncCount > 0) {
      const t = setTimeout(() => syncData(), 3000);
      return () => clearTimeout(t);
    }
  }, [isOnline, pendingSyncCount, syncData]);

  useEffect(() => {
    if (state.user) localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...state, transactions: [], savings: [] }));
  }, [state]);

  useEffect(() => {
    if (state.business?.isActive && state.transactions.length > 0) getBusinessInsight(state.business, state.transactions).then(setInsight);
  }, [state.business, state.transactions]);

  const addTransaction = async (type: 'sale' | 'expense', amount: number, category: string) => {
    const newTx: LocalTransaction = { 
      id: crypto.randomUUID(), 
      userId: state.user?.phoneNumber || 'anon', 
      type, amount, category, date: new Date().toISOString().split('T')[0], 
      synced: 0, client_updated_at: Date.now() 
    };
    await db.transactions.add(newTx);
    setState(prev => ({ ...prev, transactions: [...prev.transactions, newTx], entryCount: prev.entryCount + 1 }));
    await updateCount();
    if (isOnline) syncData();
  };

  const addSaving = async (amount: number, destination: 'Bank' | 'Mobile Money') => {
    const newS: LocalSaving = { 
      id: crypto.randomUUID(), 
      businessId: state.business?.id || 'anon', 
      amount, destination, date: new Date().toISOString().split('T')[0], 
      synced: 0, client_updated_at: Date.now() 
    };
    await db.savings.add(newS);
    setState(prev => ({ ...prev, savings: [...prev.savings, newS] }));
    await updateCount();
    if (isOnline) syncData();
  };

  const handleOnboarding = async (business: Business) => {
    const phone = state.user?.phoneNumber;
    const { data: profile } = await supabase.from('profiles').select('id').eq('phone', phone).single();
    if (profile) {
      const { data: biz } = await supabase.from('businesses').insert({ user_id: profile.id, name: business.name, type: business.type, isActive: false, start_date: business.startDate }).select().single();
      await supabase.from('profiles').update({ has_completed_onboarding: true }).eq('id', profile.id);
      setState(prev => ({ ...prev, business: { ...business, id: biz.id }, user: prev.user ? { ...prev.user, hasCompletedOnboarding: true } : null }));
    }
  };

  if (isInitializing) return <SplashScreen />;

  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={<LandingPage user={state.user} />} />
        <Route path="/login" element={!state.user ? <AuthPage onAuthComplete={(p) => setState(prev => ({...prev, user: { phoneNumber: p.phone, name: p.name, isAdmin: p.is_admin, hasCompletedOnboarding: p.has_completed_onboarding }}))} onMissingTables={() => {}} /> : <Navigate to="/dashboard" replace />} />
        <Route path="/onboarding" element={state.user?.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <OnboardingPage onComplete={handleOnboarding} />} />
        <Route path="/dashboard" element={state.user?.hasCompletedOnboarding ? (state.business?.isActive ? <Dashboard state={state} onLogout={() => setShowLogoutConfirm(true)} insight={insight} onShowCategoryPrompt={() => {}} isOnline={isOnline} pendingSyncCount={pendingSyncCount} isSyncing={isSyncing} onSync={syncData} /> : <PendingActivationPage onLogout={() => setShowLogoutConfirm(true)} />) : <Navigate to="/login" replace />} />
        <Route path="/savings" element={<SavingsHub state={state} />} />
        <Route path="/record-saving" element={<RecordSavingPage onSave={addSaving} />} />
        <Route path="/record/:type" element={<RecordPage type={(useParams() as any).type} onSave={addTransaction} />} />
        <Route path="/admin" element={<AdminDashboard user={state.user!} onLogout={() => setShowLogoutConfirm(true)} />} />
      </Routes>
      {showLogoutConfirm && <LogoutConfirmModal onConfirm={() => { localStorage.removeItem(STORAGE_KEY); db.transactions.clear(); db.savings.clear(); setState(initialState); setShowLogoutConfirm(false); }} onCancel={() => setShowLogoutConfirm(false)} />}
    </HashRouter>
  );
}

