const AuthPage: React.FC<{ 
  onAuthComplete: (profile: any) => void;
  onMissingTables: () => void;
}> = ({ onAuthComplete, onMissingTables }) => {
  const [phone, setPhone] = useState('');
  const [code, setCode] = useState('');
  const [name, setName] = useState('');
  const [step, setStep] = useState<'input' | 'verify'>('input');
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSendOtp = async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: funcError } = await supabase.functions.invoke('otp-handler', {
        body: { action: 'send', phone, mode, name }
      });
      if (funcError) throw funcError;
      if (data.success === false) {
        setError(data.error);
        return;
      }
      setStep('verify');
    } catch (err: any) {
      setError(err.message || 'Failed to send code');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: funcError } = await supabase.functions.invoke('otp-handler', {
        body: { action: 'verify', phone, code, name }
      });
      if (funcError) throw funcError;
      if (data.success) {
        onAuthComplete(data.profile);
      } else {
        setError(data.error || 'Invalid code');
      }
    } catch (err: any) {
      setError(err.message || 'Verification failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
      <Card className="w-full max-w-md space-y-6">
        <div className="text-center space-y-2">
          <h2 className="text-2xl font-bold text-slate-900">{step === 'input' ? (mode === 'login' ? 'Welcome Back' : 'Create Account') : 'Verify Phone'}</h2>
          <p className="text-slate-500">{step === 'input' ? 'Enter your phone number to continue' : `Enter code sent to ${phone}`}</p>
        </div>
        {error && <div className="p-3 bg-rose-50 text-rose-600 rounded-xl text-sm font-medium">{error}</div>}
        <div className="space-y-4">
          {step === 'input' ? (
            <>
              {mode === 'register' && <Input label="Full Name" value={name} onChange={e => setName(e.target.value)} />}
              <Input label="Phone Number" placeholder="050 000 0000" type="tel" value={phone} onChange={e => setPhone(e.target.value)} />
              <Button className="w-full" onClick={handleSendOtp} disabled={loading}>{loading ? <Loader2 className="animate-spin"/> : 'Continue'}</Button>
              <button onClick={() => setMode(mode === 'login' ? 'register' : 'login')} className="w-full text-sm font-bold text-purple-600">
                {mode === 'login' ? "Don't have an account? Register" : "Already have an account? Login"}
              </button>
            </>
          ) : (
            <>
              <Input label="Verification Code" placeholder="000000" type="number" value={code} onChange={e => setCode(e.target.value)} />
              <Button className="w-full" onClick={handleVerifyOtp} disabled={loading}>{loading ? <Loader2 className="animate-spin"/> : 'Verify & Login'}</Button>
              <button onClick={() => setStep('input')} className="w-full text-sm font-bold text-slate-500">Back</button>
            </>
          )}
        </div>
      </Card>
    </div>
  );
};

