        <div className="space-y-2">
          <h2 className="text-2xl font-black text-slate-900">Cloud Sync</h2>
          <p className="text-slate-500 text-sm">
            {isSyncing ? 'Backing up your business records to our secure servers...' : 'Review your synchronization status.'}
          </p>
        </div>

        <div className="space-y-4 pt-2">
          <div className="space-y-1">
            <div className="flex justify-between text-xs font-bold uppercase tracking-widest text-slate-400">
              <span>Unsynced Records</span>
              <span>{pendingCount} remaining</span>
            </div>
            <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-purple-600 transition-all duration-500" 
                style={{ width: `${pendingCount > 0 ? 30 : 100}%` }}
              />
            </div>
          </div>

          <div className="p-4 bg-slate-50 rounded-2xl flex gap-3 items-center">
            <div className={`w-3 h-3 rounded-full ${navigator.onLine ? 'bg-emerald-500' : 'bg-rose-500'}`} />
            <span className="text-sm font-bold text-slate-700">
              {navigator.onLine ? 'Network Connected' : 'No Internet Connection'}
            </span>
          </div>
        </div>

        <div className="flex flex-col gap-3 pt-4">
          <Button 
            size="lg" 
            className="w-full" 
            onClick={onStartSync} 
            disabled={isSyncing || !navigator.onLine || pendingCount === 0}
          >
            {isSyncing ? 'Syncing...' : 'Sync Now'}
          </Button>
          <button onClick={onClose} className="text-slate-400 font-bold py-2 hover:text-slate-600 transition-colors">
            Close
          </button>
        </div>
      </Card>
    </div>
  );
};

