const AdminDashboard: React.FC<{ user: User; onLogout: () => void }> = ({ user, onLogout }) => {
  const [businesses, setBusinesses] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();
  const fetchAll = async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase.from('businesses').select('*, profiles:user_id (phone, name)').order('created_at', { ascending: false });
      if (error) throw error;
      setBusinesses(data || []);
    } catch (err) { console.error(err); } 
    finally { setIsLoading(false); }
  };
  useEffect(() => { if (!user.isAdmin) navigate('/dashboard'); else fetchAll(); }, [user]);
  const toggle = async (id: string, status: boolean) => {
    try {
      await supabase.from('businesses').update({ is_active: !status }).eq('id', id);
      setBusinesses(prev => prev.map(b => b.id === id ? { ...b, is_active: !status } : b));
    } catch (err) { alert("Failed to update"); }
  };
  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-purple-700 text-white p-6 shadow-lg flex justify-between items-center"><h1 className="text-2xl font-black">DigiShe Admin</h1><div className="flex gap-4"><Button variant="outline" className="!text-white border-white/30" onClick={() => navigate('/dashboard')}>App</Button><button onClick={onLogout} className="p-2 hover:text-rose-300"><LogOut size={24} /></button></div></header>
      <main className="max-w-6xl auto w-full p-6 flex-1"><Card className="overflow-hidden p-0 shadow-xl"><div className="bg-white border-b p-6 flex justify-between items-center"><h2 className="text-xl font-bold">Managed Businesses</h2><Button size="sm" onClick={fetchAll}>{isLoading ? <Loader2 className="animate-spin" size={16} /> : <RefreshCw size={16} />} Refresh</Button></div>
          <div className="overflow-x-auto"><table className="w-full text-left"><thead><tr className="bg-slate-50 text-slate-500 text-xs font-black uppercase tracking-widest border-b"><th className="px-6 py-4">Business & Owner</th><th className="px-6 py-4">Status</th><th className="px-6 py-4 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-50">{businesses.map(b => (<tr key={b.id} className="hover:bg-slate-50/50"><td className="px-6 py-4"><p className="font-bold">{b.name}</p><p className="text-xs text-slate-500">{b.profiles?.phone}</p></td><td className="px-6 py-4"><span className={`px-3 py-1 rounded-full text-xs font-black uppercase ${b.is_active ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>{b.is_active ? 'Active' : 'Pending'}</span></td><td className="px-6 py-4 text-right"><Button size="sm" variant={b.is_active ? 'outline' : 'primary'} onClick={() => toggle(b.id, b.is_active)}>{b.is_active ? <Lock size={14} /> : <Unlock size={14} />}</Button></td></tr>))}</tbody></table></div></Card></main>
    </div>
  );
};

const AuthPage: React.FC<{ onAuthComplete: (profile: any) => void; onMissingTables: () => void }> = ({ onAuthComplete, onMissingTables }) => {
  const [step, setStep] = useState<'phone' | 'otp'>('phone');
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [code, setCode] = useState('');
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const handleSendOTP = async () => {
    if (!phone) return setError('Enter your phone number');
    setIsLoading(true); setError(null);
    try {
      const normalized = normalizePhone(phone);
      const { data, error: invokeError } = await supabase.functions.invoke('otp-handler', { body: { action: 'send', phone: normalized, mode, name } });
      if (invokeError) throw invokeError;
      if (data?.success === false) setError(data.error); else setStep('otp');
    } catch (err: any) { setError(err.message || 'Failed'); } finally { setIsLoading(false); }
  };
  const handleVerifyOTP = async () => {
    if (!code) return setError('Enter the code');
    setIsLoading(true); setError(null);
    try {
      const normalized = normalizePhone(phone);
      const { data, error: invokeError } = await supabase.functions.invoke('otp-handler', { body: { action: 'verify', phone: normalized, code, name } });
      if (invokeError) throw invokeError;
      if (data?.success) onAuthComplete(data.profile); else setError(mapArkeselError(data.code || 1104));
    } catch (err: any) { setError(err.message || 'Failed'); } finally { setIsLoading(false); }
  };
  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6"><Card className="max-w-md w-full p-8 space-y-8 shadow-xl"><div className="text-center space-y-2"><div className="bg-purple-100 w-16 h-16 rounded-3xl flex items-center justify-center text-purple-600 mx-auto mb-4"><Store size={32} /></div><h2 className="text-3xl font-black">{step === 'phone' ? (mode === 'login' ? 'Welcome Back' : 'Join DigiShe') : 'Check Phone'}</h2><p className="text-slate-500 font-medium">{step === 'phone' ? 'Enter details to continue.' : `Enter code sent to ${phone}`}</p></div>
        {error && <div className="bg-rose-50 text-rose-600 p-4 rounded-xl text-sm font-bold">{error}</div>}
        <div className="space-y-4">{step === 'phone' ? (<>{mode === 'register' && <Input label="Name" value={name} onChange={e => setName(e.target.value)} />}<Input label="Phone" type="tel" value={phone} onChange={e => setPhone(e.target.value)} /><div className="flex gap-2 p-1 bg-slate-100 rounded-xl"><button onClick={() => setMode('login')} className={`flex-1 py-2 text-xs font-black rounded-lg ${mode === 'login' ? 'bg-white text-purple-600 shadow-sm' : 'text-slate-400'}`}>Login</button><button onClick={() => setMode('register')} className={`flex-1 py-2 text-xs font-black rounded-lg ${mode === 'register' ? 'bg-white text-purple-600 shadow-sm' : 'text-slate-400'}`}>Register</button></div><Button size="lg" className="w-full mt-4" onClick={handleSendOTP} disabled={isLoading}>{isLoading ? <Loader2 className="animate-spin" /> : 'Send Code'}</Button></>) : (<><Input label="Code" type="number" value={code} onChange={e => setCode(e.target.value)} /><Button size="lg" className="w-full mt-4" onClick={handleVerifyOTP} disabled={isLoading}>{isLoading ? <Loader2 className="animate-spin" /> : 'Verify'}</Button><button onClick={() => setStep('phone')} className="w-full text-slate-400 font-bold py-2">Change phone</button></>)}</div><button onClick={onMissingTables} className="w-full text-[10px] text-slate-300 font-bold uppercase hover:text-slate-400">Setup database</button></Card></div>
  );
};

