const RecordRouteHandler: React.FC<{ user: User | null, business: Business | null, customCategories: string[], transactions: Transaction[], onSave: (type: 'sale' | 'expense', amount: number, category: string) => void }> = ({ user, business, customCategories, onSave }) => {
