import Dexie, { type Table } from 'dexie';
import { Transaction, Saving } from '../types';

export interface LocalTransaction extends Transaction {
  synced: number; // 0 = unsynced, 1 = synced
  client_updated_at: number;
}

export interface LocalSaving extends Saving {
  synced: number;
  client_updated_at: number;
}

export class DigiSheDB extends Dexie {
  transactions!: Table<LocalTransaction>;
  savings!: Table<LocalSaving>;

  constructor() {
    super('DigiSheDB');
    this.version(1).stores({
      // Primary keys and indexed fields for efficient querying
      // Adding businessId to indices to support robust multi-business data segregation if needed in future
      transactions: 'id, businessId, userId, type, synced, date, client_updated_at',
      savings: 'id, businessId, synced, date, client_updated_at'
    });
  }
}

