      <Card className="max-w-2xl w-full max-h-[90vh] overflow-hidden flex flex-col p-0 border-none shadow-2xl">
        <div className="p-6 bg-purple-600 text-white flex justify-between items-center"><div className="flex items-center gap-3"><Database size={24} /><h2 className="text-xl font-bold">Setup Guide</h2></div><button onClick={onClose}><XCircle size={24} /></button></div>
