const SALES_CATEGORIES = ['Product sold', 'Service rendered', 'Other sales'];
const EXPENSE_CATEGORIES = ['Materials', 'Transport', 'Rent', 'Light Bill', 'Water Bill', 'Food', 'Other expenses'];

// Optimized SQL setup for Supabase
const SQL_SETUP = `-- DigiShe Database Setup
-- Run this in your Supabase SQL Editor

-- 1. Profiles table
CREATE TABLE IF NOT EXISTS profiles (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  phone TEXT UNIQUE NOT NULL,
  name TEXT,
  has_completed_onboarding BOOLEAN DEFAULT FALSE,
  is_admin BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- 2. Businesses table
CREATE TABLE IF NOT EXISTS businesses (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID REFERENCES profiles(id) ON DELETE CASCADE NOT NULL,
  name TEXT NOT NULL,
  type TEXT NOT NULL,
  location TEXT,
  is_active BOOLEAN DEFAULT FALSE,
  start_date DATE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- 3. Transactions table
CREATE TABLE IF NOT EXISTS transactions (
  id UUID PRIMARY KEY,
  business_id UUID REFERENCES businesses(id) ON DELETE CASCADE NOT NULL,
  type TEXT CHECK (type IN ('sale', 'expense')) NOT NULL,
  amount NUMERIC NOT NULL,
  category TEXT NOT NULL,
  date DATE NOT NULL,
  client_updated_at BIGINT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- 4. Savings table
CREATE TABLE IF NOT EXISTS savings (
  id UUID PRIMARY KEY,
  business_id UUID REFERENCES businesses(id) ON DELETE CASCADE NOT NULL,
  amount NUMERIC NOT NULL,
  destination TEXT CHECK (destination IN ('Bank', 'Mobile Money')) NOT NULL,
  date DATE NOT NULL,
  client_updated_at BIGINT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::TEXT, NOW()) NOT NULL
);

-- Enable RLS and add public access policies
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE businesses ENABLE ROW LEVEL SECURITY;
ALTER TABLE transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE savings ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public access to profiles" ON profiles FOR ALL USING (true);
CREATE POLICY "Allow public access to businesses" ON businesses FOR ALL USING (true);
CREATE POLICY "Allow public access to transactions" ON transactions FOR ALL USING (true);
CREATE POLICY "Allow public access to savings" ON savings FOR ALL USING (true);`;

const initialState: AppState = {
  user: null,
  business: null,
  transactions: [],
  savings: [],
  customCategories: [],
  entryCount: 0,
  showCategoryPrompt: false
};

// --- Helper Functions ---
const formatDate = (date: Date) => date.toISOString().split('T')[0];

const normalizePhone = (phone: string): string => {
  if (!phone) return '';
  let cleaned = phone.replace(/\D/g, '');
  if (cleaned.startsWith('2330') && cleaned.length === 13) {
    cleaned = '233' + cleaned.substring(4);
  }
  else if (cleaned.startsWith('0') && cleaned.length === 10) {
    cleaned = '233' + cleaned.substring(1);
  } 
  else if (cleaned.length === 9) {
    cleaned = '233' + cleaned;
  }
  return cleaned;
};

const getWeeklyData = (transactions: Transaction[]) => {
  const last7Days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return formatDate(d);
  }).reverse();

  return last7Days.map(date => {
    const daily = transactions.filter(t => t.date === date);
    return {
      date: new Date(date).toLocaleDateString('en-US', { weekday: 'short' }),
      fullDate: date,
      sales: daily.filter(t => t.type === 'sale').reduce((acc, t) => acc + t.amount, 0),
      expenses: daily.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0)
    };
  });
};

const mapArkeselError = (code: string | number) => {
  const codeStr = String(code);
  const errors: Record<string, string> = {
    '1005': 'Invalid phone format. Please enter a valid number.',
    '1007': 'SMS service is currently unavailable. Contact support.',
    '1104': 'Incorrect verification code. Please try again.',
    '1105': 'Code expired. Please request a new one.',
  };
  return errors[codeStr] || `Error: ${codeStr}`;
};

