const AuthPage: React.FC<{ onAuthComplete: (profile: any) => void; onMissingTables: () => void }> = ({ onAuthComplete, onMissingTables }) => {
  const [step, setStep] = useState<'phone' | 'otp'>('phone');
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [code, setCode] = useState('');
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSendOTP = async () => {
    if (!phone) return setError('Enter your phone number');
    setIsLoading(true); setError(null);
    try {
      const normalized = normalizePhone(phone);
      const { data, error: invokeError } = await supabase.functions.invoke('otp-handler', { body: { action: 'send', phone: normalized, mode, name } });
      if (invokeError) throw invokeError;
      if (data?.success === false) setError(data.error); else setStep('otp');
    } catch (err: any) { setError(err.message || 'Failed'); } finally { setIsLoading(false); }
  };

  const handleVerifyOTP = async () => {
    if (!code) return setError('Enter the code');
    setIsLoading(true); setError(null);
    try {
      const normalized = normalizePhone(phone);
      const { data, error: invokeError } = await supabase.functions.invoke('otp-handler', { body: { action: 'verify', phone: normalized, code, name } });
      if (invokeError) throw invokeError;
      if (data?.success) onAuthComplete(data.profile); else setError(mapArkeselError(data.code || 1104));
    } catch (err: any) { setError(err.message || 'Failed'); } finally { setIsLoading(false); }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
      <Card className="max-w-md w-full p-8 space-y-8 shadow-xl">
        <div className="text-center space-y-2">
          <div className="bg-purple-100 w-16 h-16 rounded-3xl flex items-center justify-center text-purple-600 mx-auto mb-4"><Store size={32} /></div>
          <h2 className="text-3xl font-black">{step === 'phone' ? (mode === 'login' ? 'Welcome Back' : 'Join DigiShe') : 'Check Phone'}</h2>
          <p className="text-slate-500 font-medium">{step === 'phone' ? 'Enter details to continue.' : `Enter code sent to ${phone}`}</p>
        </div>
        {error && <div className="bg-rose-50 text-rose-600 p-4 rounded-xl text-sm font-bold">{error}</div>}
        <div className="space-y-4">
          {step === 'phone' ? (
            <>
              {mode === 'register' && <Input label="Name" value={name} onChange={e => setName(e.target.value)} />}
              <Input label="Phone Number" type="tel" value={phone} onChange={e => setPhone(e.target.value)} placeholder="050 000 0000" />
              <div className="flex gap-2 p-1 bg-slate-100 rounded-xl">
                <button onClick={() => setMode('login')} className={`flex-1 py-2 text-xs font-black rounded-lg ${mode === 'login' ? 'bg-white text-purple-600 shadow-sm' : 'text-slate-400'}`}>Login</button>
                <button onClick={() => setMode('register')} className={`flex-1 py-2 text-xs font-black rounded-lg ${mode === 'register' ? 'bg-white text-purple-600 shadow-sm' : 'text-slate-400'}`}>Register</button>
              </div>
              <Button size="lg" className="w-full mt-4" onClick={handleSendOTP} disabled={isLoading}>{isLoading ? <Loader2 className="animate-spin" /> : 'Send Code'}</Button>
            </>
          ) : (
            <>
              <Input label="Verification Code" type="number" value={code} onChange={e => setCode(e.target.value)} placeholder="123456" />
              <Button size="lg" className="w-full mt-4" onClick={handleVerifyOTP} disabled={isLoading}>{isLoading ? <Loader2 className="animate-spin" /> : 'Verify'}</Button>
              <button onClick={() => setStep('phone')} className="w-full text-slate-400 font-bold py-2">Change phone number</button>
            </>
          )}
        </div>
        <button onClick={onMissingTables} className="w-full text-[10px] text-slate-300 font-bold uppercase hover:text-slate-400">Setup Cloud Database</button>
      </Card>
    </div>
  );
};

