// --- Main App ---
export default function App() {
  const [state, setState] = useState<AppState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : initialState;
    } catch (e) { return initialState; }
  });

  const [insight, setInsight] = useState("Keep up the great work!");
  const [showSetup, setShowSetup] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [showCatCreator, setShowCatCreator] = useState(false);
  const [showSyncModal, setShowSyncModal] = useState(false);

  const [isInitializing, setIsInitializing] = useState(true);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isRefreshingStatus, setIsRefreshingStatus] = useState(false);
  const [pendingSyncCount, setPendingSyncCount] = useState(0);

  const syncInProgressRef = useRef(false);

  const updatePendingCount = useCallback(async () => {
    try {
      const unsyncedTx = await db.transactions.where('synced').equals(0).count();
      const unsyncedSv = await db.savings.where('synced').equals(0).count();
      setPendingSyncCount(unsyncedTx + unsyncedSv);
    } catch (err) {
      console.error("Count Update Error:", err);
    }
  }, []);

  const pullCloudData = useCallback(async (businessId: string, userPhone: string) => {
    if (!navigator.onLine) return;
    try {
      console.log(`Starting cloud pull for business: ${businessId}`);
      // Pull Transactions
      const { data: cloudTxs, error: txError } = await supabase.from('transactions').select('*').eq('business_id', businessId);
      if (txError) throw txError;

      if (cloudTxs) {
        const localTxs: LocalTransaction[] = cloudTxs.map(t => ({
          id: t.id,
          userId: userPhone,
          businessId: businessId,
          type: t.type,
          amount: typeof t.amount === 'string' ? parseFloat(t.amount) : t.amount,
          category: t.category,
          date: t.date,
          synced: 1,
          client_updated_at: Number(t.client_updated_at) || Date.now()
        }));
        await db.transactions.bulkPut(localTxs);
      }

      // Pull Savings
      const { data: cloudSvs, error: svError } = await supabase.from('savings').select('*').eq('business_id', businessId);
      if (svError) throw svError;

      if (cloudSvs) {
        const localSvs: LocalSaving[] = cloudSvs.map(s => ({
          id: s.id,
          businessId: businessId,
          amount: typeof s.amount === 'string' ? parseFloat(s.amount) : s.amount,
          destination: s.destination,
          date: s.date,
          synced: 1,
          client_updated_at: Number(s.client_updated_at) || Date.now()
        }));
        await db.savings.bulkPut(localSvs);
      }

      const finalTxs = await db.transactions.toArray();
      const finalSvs = await db.savings.toArray();

      setState(prev => ({
        ...prev,
        transactions: finalTxs,
        savings: finalSvs,
        entryCount: finalTxs.length
      }));

      await updatePendingCount();
    } catch (err) {
      console.error("Cloud Pull Error:", err);
    }
  }, [updatePendingCount]);

  const startSync = useCallback(async () => {
    const businessId = state.business?.id;
    const userPhone = state.user?.phoneNumber;

    if (!navigator.onLine || syncInProgressRef.current || !businessId || !userPhone) {
      console.log("Sync skipped: No connection, already in progress, or no business ID.");
      return;
    }

    syncInProgressRef.current = true;
    setIsSyncing(true);

    try {
      console.log("Starting batch sync...");
      // 1. Fetch unsynced transactions
      const unsyncedTx = await db.transactions.where('synced').equals(0).toArray();
      if (unsyncedTx.length > 0) {
        const txPayload = unsyncedTx.map(tx => ({
          id: tx.id,
          business_id: businessId,
          type: tx.type,
          amount: tx.amount,
          category: tx.category,
          date: tx.date,
          client_updated_at: tx.client_updated_at
        }));

        const { error: txError } = await supabase.from('transactions').upsert(txPayload);
        if (txError) throw txError;

        // Update local status
        const ids = unsyncedTx.map(tx => tx.id);
        await db.transactions.where('id').anyOf(ids).modify({ synced: 1 });
        console.log(`Synced ${unsyncedTx.length} transactions.`);
      }

      // 2. Fetch unsynced savings
      const unsyncedSv = await db.savings.where('synced').equals(0).toArray();
      if (unsyncedSv.length > 0) {
        const svPayload = unsyncedSv.map(sv => ({
          id: sv.id,
          business_id: businessId,
          amount: sv.amount,
          destination: sv.destination,
          date: sv.date,
          client_updated_at: sv.client_updated_at
        }));

        const { error: svError } = await supabase.from('savings').upsert(svPayload);
        if (svError) throw svError;

        const ids = unsyncedSv.map(sv => sv.id);
        await db.savings.where('id').anyOf(ids).modify({ synced: 1 });
        console.log(`Synced ${unsyncedSv.length} savings.`);
      }

      // 3. Pull latest data from cloud to resolve any conflicts and update local store
      await pullCloudData(businessId, userPhone);

      console.log("Batch sync completed successfully.");
    } catch (err) {
      console.error("Sync Operation Failed:", err);
    } finally {
      syncInProgressRef.current = false;
      setTimeout(() => setIsSyncing(false), 500);
      await updatePendingCount();
    }
  }, [state.business?.id, state.user?.phoneNumber, pullCloudData, updatePendingCount]);

  const refreshBusinessStatus = useCallback(async (userId?: string) => {
    if (!navigator.onLine) return;

    let phoneToUse = userId;
    if (!phoneToUse) {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        phoneToUse = parsed.user?.phoneNumber;
      }
    }

    if (!phoneToUse) return;

    setIsRefreshingStatus(true);
    try {
      const normalized = normalizePhone(phoneToUse);
      const { data: profile } = await supabase.from('profiles').select('id').eq('phone', normalized).single();

      if (profile) {
        const { data: businessData } = await supabase.from('businesses').select('*').eq('user_id', profile.id).maybeSingle();

        if (businessData) {
          const isActuallyActive = businessData.is_active;

          setState(prev => ({
            ...prev,
            business: {
              ...prev.business,
              id: businessData.id,
              name: businessData.name,
              type: businessData.type as BusinessType,
              location: businessData.location,
              startDate: businessData.start_date,
              isActive: isActuallyActive
            }
          }));

          // Try to sync if active
          if (isActuallyActive) {
            await pullCloudData(businessData.id, normalized);
          }
        }
      }
    } catch (err) {
      console.error("Status Refresh Error:", err);
    } finally {
      setIsRefreshingStatus(false);
    }
  }, [pullCloudData]);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    const init = async () => {
      const txs = await db.transactions.toArray();
      const svs = await db.savings.toArray();

      const stored = localStorage.getItem(STORAGE_KEY);
      const parsed = stored ? JSON.parse(stored) : initialState;

      setState(prev => ({
        ...parsed,
        transactions: txs,
        savings: svs,
        entryCount: txs.length
      }));

      await updatePendingCount();

      if (parsed.user && navigator.onLine) {
        refreshBusinessStatus(parsed.user.phoneNumber);
      }

      setIsInitializing(false);
    };
    init();
  }, [updatePendingCount, refreshBusinessStatus]);

  useEffect(() => {
    if (state.user) localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [state]);

  useEffect(() => {
    if (isOnline && pendingSyncCount > 0 && !isSyncing) {
      const timer = setTimeout(() => startSync(), 2000);
      return () => clearTimeout(timer);
    }
  }, [isOnline, pendingSyncCount, isSyncing, startSync]);

  useEffect(() => {
    if (state.business?.isActive && state.transactions.length > 0) {
      const txLen = state.transactions.length;
      if (txLen % 3 === 0 || insight === "Keep up the great work!") {
         getBusinessInsight(state.business, state.transactions).then(setInsight);
      }
    }
  }, [state.business, state.transactions, insight]);

  const addTransaction = async (type: 'sale' | 'expense', amount: number, category: string) => {
    if (!state.user || !state.business?.id) {
      console.error("Missing user or business ID for transaction");
      return;
    }
    const normalized = normalizePhone(state.user.phoneNumber);
    const businessId = state.business.id;
    const dateStr = formatDate(new Date());
    const now = Date.now();

    const newTx: LocalTransaction = { 
      id: crypto.randomUUID(), 
      userId: normalized, 
      businessId: businessId,
      type, 
      amount, 
      category, 
      date: dateStr,
      synced: 0,
      client_updated_at: now
    };

    await db.transactions.add(newTx);
    await updatePendingCount();
    setState(prev => ({ 
      ...prev, 
      transactions: [...prev.transactions, newTx], 
      entryCount: prev.entryCount + 1,
      showCategoryPrompt: (prev.entryCount + 1) === 3
    }));
  };

  const addSaving = async (amount: number, destination: 'Bank' | 'Mobile Money') => {
    if (!state.user || !state.business?.id) return;
    const businessId = state.business.id;
    const dateStr = formatDate(new Date());
    const now = Date.now();
    const newS: LocalSaving = { 
      id: crypto.randomUUID(), 
      businessId: businessId, 
      amount, 
      destination, 
      date: dateStr,
      synced: 0,
      client_updated_at: now
    };
    await db.savings.add(newS);
    await updatePendingCount();
    setState(prev => ({ ...prev, savings: [...prev.savings, newS] }));
  };

  const handleOnboarding = async (business: Business) => {
    if (!state.user) return;
    const normalized = normalizePhone(state.user.phoneNumber);
    const { data: profile } = await supabase.from('profiles').select('id').eq('phone', normalized).single();
    if (profile) {
      const { data: newBiz, error: bizError } = await supabase.from('businesses').insert({ 
        user_id: profile.id, 
        name: business.name, 
        type: business.type, 
        location: business.location, 
        is_active: false, 
        start_date: formatDate(new Date(business.startDate))
      }).select().single();
      if (bizError) throw bizError;
      await supabase.from('profiles').update({ has_completed_onboarding: true }).eq('id', profile.id);
      setState(prev => ({ 
        ...prev, 
        business: { ...business, id: newBiz.id, isActive: false }, 
        user: prev.user ? { ...prev.user, hasCompletedOnboarding: true } : null 
      }));
    }
  };

  const handleAuthComplete = useCallback((p: any) => {
    const normalized = normalizePhone(p.phone);
    setState(prev => ({
      ...prev, 
      user: { 
        phoneNumber: normalized, 
        name: p.name, 
        isAdmin: p.is_admin, 
        hasCompletedOnboarding: p.has_completed_onboarding 
      }
    }));
    if (navigator.onLine) refreshBusinessStatus(normalized);
  }, [refreshBusinessStatus]);

  const performLogout = () => { 
    localStorage.removeItem(STORAGE_KEY); 
    db.transactions.clear();
    db.savings.clear();
    setState({ ...initialState }); 
    setInsight("Keep up the great work!"); 
    setShowLogoutConfirm(false); 
  };

  const user = state.user;
  const business = state.business;

  if (isInitializing) return <SplashScreen />;

  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={<LandingPage user={user} />} />
        <Route path="/login" element={!user ? <AuthPage onAuthComplete={handleAuthComplete} onMissingTables={() => setShowSetup(true)} /> : (user.hasCompletedOnboarding ? (business?.isActive ? <Navigate to="/dashboard" replace /> : <Navigate to="/pending" replace />) : <Navigate to="/onboarding" replace />)} />
        <Route path="/onboarding" element={user ? (user.hasCompletedOnboarding ? <Navigate to="/dashboard" replace /> : <OnboardingPage onComplete={handleOnboarding} />) : <Navigate to="/login" replace />} />
        <Route path="/pending" element={user?.hasCompletedOnboarding ? (business?.isActive ? <Navigate to="/dashboard" replace /> : <PendingActivationPage onLogout={() => setShowLogoutConfirm(true)} onRefresh={() => refreshBusinessStatus()} isRefreshing={isRefreshingStatus} />) : <Navigate to="/login" replace />} />
        <Route path="/admin" element={user?.isAdmin ? <AdminDashboard user={user} onLogout={() => setShowLogoutConfirm(true)} /> : <Navigate to="/dashboard" replace />} />
        <Route path="/dashboard" element={user?.hasCompletedOnboarding ? (business?.isActive ? <Dashboard state={state} onLogout={() => setShowLogoutConfirm(true)} insight={insight} onShowCategoryPrompt={() => { if(state.entryCount >= 3) setShowCatCreator(true); }} isOnline={isOnline} pendingCount={pendingSyncCount} isSyncing={isSyncing} onOpenSyncModal={() => setShowSyncModal(true)} /> : <Navigate to="/pending" replace />) : <Navigate to="/login" replace />} />
        <Route path="/savings" element={user?.hasCompletedOnboarding ? (business?.isActive ? <SavingsHub state={state} /> : <Navigate to="/pending" replace />) : <Navigate to="/login" replace />} />
        <Route path="/record-saving" element={user?.hasCompletedOnboarding ? (business?.isActive ? <RecordSavingPage onSave={addSaving} /> : <Navigate to="/pending" replace />) : <Navigate to="/login" replace />} />
        <Route path="/record/:type" element={<RecordRouteHandler user={user} business={business} customCategories={state.customCategories} transactions={state.transactions} onSave={addTransaction} />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
      {showSetup && <DatabaseSetupModal onClose={() => setShowSetup(false)} />}
      {showLogoutConfirm && <LogoutConfirmModal onConfirm={performLogout} onCancel={() => setShowLogoutConfirm(false)} />}
      {showCatCreator && <CreateCategoryModal onAdd={(name) => {
          setState(prev => ({ ...prev, customCategories: [...prev.customCategories, name], showCategoryPrompt: false }));
          setShowCatCreator(false);
        }} onCancel={() => { setShowCatCreator(false); setState(prev => ({ ...prev, showCategoryPrompt: false })); }} />}
      {showSyncModal && <ManualSyncModal onClose={() => setShowSyncModal(false)} isSyncing={isSyncing} pendingCount={pendingSyncCount} onStartSync={startSync} />}
    </HashRouter>
  );
}

