  const { type } = useParams<{ type: string }>();
  if (!user || !business) return <Navigate to="/login" replace />;
  if (type !== 'sale' && type !== 'expense') return <Navigate to="/dashboard" replace />;
  return <RecordPage type={type} customCategories={customCategories} onSave={onSave} />;
};

